// accent colour for two-tone emblems: the livery stripe when it stands out from the tail, else a softer version of the main colour
function logoAccent(lv,col){if(lv.logoAcc)return lv.logoAcc;const st=lv.stripe||col;return st.toLowerCase()!==String(col).toLowerCase()&&Math.abs(lum(st)-lum(lv.tail))>.15?st:null}
// own logo colours (logoCol on the tail colour, logoAcc for the second tone) override the automatic ones
function logoSVG(lv,size,col){const L=LOGOS[lv.logo]||LOGOS.bird;if(lv.logoCol&&col===onCol(lv.tail))col=lv.logoCol;
  if(Array.isArray(L[1])){const acc=logoAccent(lv,col);
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" aria-hidden="true">${L[1].map(([d,r,tf])=>`<path d="${d}"${tf?` transform="${tf}"`:""} style="fill:${r==="b"?(acc||col):col}"${r==="b"&&!acc?' opacity=".6"':""}/>`).join("")}</svg>`}
  if(L[1]==="mono"){const acc=logoAccent(lv,col)||col;
    return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" aria-hidden="true"><rect x="2" y="2" width="20" height="20" rx="6" fill="none" style="stroke:${col}" stroke-width="2"/><path d="M5.2 18.4c4.6-.3 9.4-1.3 13.6-3.4" fill="none" style="stroke:${acc}" stroke-width="1.6" stroke-linecap="round"/><text x="12" y="13.2" text-anchor="middle" font-family="Chakra Petch,sans-serif" font-weight="700" font-size="8.6" style="fill:${col}">${esc(S?S.code:"")}</text></svg>`}
  if(!L[1])return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" aria-hidden="true"><text x="12" y="16.5" text-anchor="middle" font-family="Chakra Petch,sans-serif" font-weight="700" font-size="12" style="fill:${col}">${esc(S.code)}</text></svg>`;
  return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" aria-hidden="true"><path d="${L[1]}" style="fill:${col}"/></svg>`}
