const SUEZ_EDGE="SUEZ|PSD";
function seaHav(a,b){const R=6371,r=Math.PI/180,dl=(b[0]-a[0])*r,dn=(b[1]-a[1])*r;const h=Math.sin(dl/2)**2+Math.cos(a[0]*r)*Math.cos(b[0]*r)*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
let SEAADJ=null;
function seaGraph(){if(SEAADJ)return SEAADJ;SEAADJ={};const add=(a,b)=>{const d=seaHav(SEAWP[a],SEAWP[b]);(SEAADJ[a]=SEAADJ[a]||[]).push([b,d]);(SEAADJ[b]=SEAADJ[b]||[]).push([a,d])};
  for(const [a,b] of SEAEDGES){if(!SEAWP[a]||!SEAWP[b])throw new Error("lane point "+a+"-"+b);add(a,b)}return SEAADJ}
const suezShut=()=>typeof S!=="undefined"&&S&&S.events&&S.events.some(e=>e.type==="suez"&&e.until>S.day);
const seaCache=new Map();
// Round every corner of a lane with a short curve so ships glide instead of zig-zagging
function smoothLane(P){if(P.length<3)return P;const out=[P[0]];
  for(let i=1;i<P.length-1;i++){const A=P[i-1],B=P[i],C=P[i+1],dAB=Math.hypot(B[0]-A[0],B[1]-A[1])||1,dBC=Math.hypot(C[0]-B[0],C[1]-B[1])||1,r=Math.min(1.8,dAB*.45,dBC*.45);
    const p1=[B[0]+(A[0]-B[0])*r/dAB,B[1]+(A[1]-B[1])*r/dAB],p2=[B[0]+(C[0]-B[0])*r/dBC,B[1]+(C[1]-B[1])*r/dBC];
    for(let k=0;k<=8;k++){const t=k/8,u=1-t;out.push([u*u*p1[0]+2*u*t*B[0]+t*t*p2[0],u*u*p1[1]+2*u*t*B[1]+t*t*p2[1]])}}
  out.push(P[P.length-1]);return out}
// Shortest lane path between two ports: [{lat,lon}...] plus distance in km
function seaPath(A,B,open){const shut=!open&&suezShut(),key=A+B+(shut?"x":"");if(seaCache.has(key))return seaCache.get(key);
  const pa=port(A),pb=port(B),G=seaGraph(),dist={},prev={},done=new Set(),Q=[];
  for(const w of pa.wp){dist[w]=seaHav([pa.lat,pa.lon],SEAWP[w]);prev[w]="@";Q.push(w)}
  const goal=new Set(pb.wp);let best=null,bestD=Infinity;
  while(Q.length){Q.sort((a,b)=>dist[a]-dist[b]);const u=Q.shift();if(done.has(u))continue;done.add(u);
    if(goal.has(u)){const t=dist[u]+seaHav(SEAWP[u],[pb.lat,pb.lon]);if(t<bestD){bestD=t;best=u}}
    if(dist[u]>bestD)break;
    for(const [v,d] of G[u]||[]){if(shut&&(u+"|"+v===SUEZ_EDGE||v+"|"+u===SUEZ_EDGE))continue;const nd=dist[u]+d;if(nd<(dist[v]??Infinity)){dist[v]=nd;prev[v]=u;Q.push(v)}}}
  if(!best){const k0=seaHav([pa.lat,pa.lon],[pb.lat,pb.lon]);const r={pts:[[pa.lat,pa.lon],[pb.lat,pb.lon]],km:Math.round(k0*1.4),via:[],cum:[0,k0]};seaCache.set(key,r);return r}
  const chain=[];for(let u=best;u&&u!=="@";u=prev[u])chain.unshift(SEAWP[u]);
  const raw=[[pa.lat,pa.lon],...chain.map(q=>[q[0],q[1]]),[pb.lat,pb.lon]];for(let i=1;i<raw.length;i++){let lo=raw[i][1];const pv=raw[i-1][1];while(lo-pv>180)lo-=360;while(lo-pv<-180)lo+=360;raw[i][1]=lo}
  const pts=smoothLane(raw);
  const via=[];for(let u=best;u&&u!=="@";u=prev[u])via.unshift(u);const cum=[0];for(let i=1;i<pts.length;i++)cum.push(cum[i-1]+seaHav(pts[i-1],pts[i]));const r={pts,km:Math.round(bestD),via,cum};seaCache.set(key,r);return r}

