/* How far each ship can sail between two ports without refuelling (km of sea route). Small coastal / feeder ships
   stay in their region; long lanes (Asia–Europe ~18,000 km, round the Cape ~25,000 km) need ocean-going ships. */
const SHIP_RNG={rfs:6000,csx:5500,fd1:6500,fmx:14000,ro3:20000,pmf:22000,ec6:26000,p10:28000,npe:30000,v20:30000,cst:5000,rfr:9000,fdr:8000,rfl:15000,fdx:10000,sub:18000,rfx:13000,ro1:14000,ro2:24000,pmx:24000,ppx:28000,eco:30000,npx:30000,vlc:30000,ulc:30000,ult:30000};
SHIPS.forEach(m=>m.rng=SHIP_RNG[m.id]||30000);
const SHIP_MAX=Math.max(...SHIPS.map(m=>m.rng));
const shipM=id=>_shipM(SHIPS,id);
function shipBadges(m){const b=[];if(m.speed>=44)b.push([_T("⚡ เร็ว"),"#D9822B"]);if(m.eco)b.push([_T("🌿 ประหยัด"),"#2F9A5E"]);if(m.reefer)b.push([_T("❄ ห้องเย็น · เรือเฉพาะ"),"#3A7BC8"]);if(m.roro)b.push([_T("🚗 ขนรถ · เรือเฉพาะ"),"#B4532A"]);if(!m.reefer&&!m.roro)b.push([_T("🔀 เรือรวม · ขนได้ทุกอย่าง"),"#5B6B80"]);if(m.deep)b.push([_T("⚓ น้ำลึก"),"#5B6B80"]);if(m.price<=2e8)b.push([_T("💰 เริ่มต้น"),"#8A6D1F"]);
  return b.length?`<span class="sbadges">${b.map(([t,c])=>`<span style="color:${c};border-color:color-mix(in srgb,${c} 40%,transparent)">${t}</span>`).join("")}</span>`:""}
const shipById=id=>_ship(S.ships,id);
const portH=m=>18+Math.sqrt(m.teu)*.25;
const sailDays=(m,km)=>km/m.speed/24;
const legDaysS=(m,km)=>sailDays(m,km)+portH(m)/24;
// container rate per box: smaller fixed part, more per km, so long-haul lanes pay best (short hops paid back in ~90 days before)
let TEU_RATE=km=>SEA_X*(700+1.05*km);
const portFee=(pt,m)=>pt.fee*1000*(m.teu/5000+.1)*(1-.15*Math.max(0,pbl(pt.c)-1))*pk("fee");
const portOpen=c=>S.unlocked.includes(port(c).reg);
const deepOK=(m,l)=>!m.deep||(port(l.from).deep&&port(l.to).deep);
// range rule uses the normal route: while the Suez Canal is shut ships detour round the Cape and refuel on the way,
// so a temporary closure never makes a ship "unable to reach" its own lane
const laneKm=l=>seaPath(l.from,l.to,true).km;
const canDock=(m,l)=>deepOK(m,l)&&m.rng>=laneKm(l);
// why a ship can't work a lane ("" when it can)
const dockWhy=(m,l)=>m.rng<laneKm(l)?_T`ไปไม่ถึง · แล่นได้ไกลสุด ${m.rng.toLocaleString()} กม. (เส้นนี้ ${laneKm(l).toLocaleString()} กม.)`:deepOK(m,l)?"":_T("เทียบท่าไม่ได้ · ต้องเป็นท่าน้ำลึกทั้งสองฝั่ง");
function evShip(c){let m=1;for(const e of S.events)if(e.port===c&&e.until>S.day&&e.pmult!=null)m*=e.pmult;return m}
function viaText(sp){const v=sp.via||[],o=[];if(v.includes("SUEZ"))o.push(_T("คลองสุเอซ"));if(v.includes("PANA"))o.push(_T("คลองปานามา"));if(v.includes("CGH"))o.push(_T("แหลมกู๊ดโฮป"));if(v.includes("HORN"))o.push(_T("แหลมฮอร์น"));if(v.includes("MLK"))o.push(_T("ช่องแคบมะละกา"));if(v.includes("LOMN"))o.push(_T("ช่องแคบลอมบอก"));return o}
/* Transshipment: containers between two ports you don't link directly are moved from ship to ship at one of your
   PORT BRANCHES — up to 3 lanes (2 transfers), if the detour is at most ~45% longer than sailing direct. One transfer
   draws 30% of a direct lane's boxes, two 18%; a lane takes at most 40% extra boxes this way. */
const XS_TEU={2:.3,3:.18},XS_CAP=.4;
const seaOwn=(a,b,km)=>80*Math.sqrt(a.w*b.w)/(1+(km/32000)**2);
let xsCache={k:null};
function seaNet(){let sig=S.day*1e6+pbList().length*7919+S.lanes.length;for(const l of S.lanes)sig+=l.id*31+l.ships.length*3;
  const key=sig+":"+pbList().join()+(suezShut()?"x":"");if(xsCache.k===key)return xsCache;
  const out={k:key,leg:new Map(),its:[]},adj=new Map(),add=(x,y,l)=>{if(!adj.has(x))adj.set(x,new Map());adj.get(x).set(y,l)};
  for(const l of S.lanes)if(l.ships.length){add(l.from,l.to,l);add(l.to,l.from,l)}
  const H=pbList(),best=new Map(),km=(x,y)=>seaPath(x,y).km;
  const consider=path=>{const X=path[0],Y=path[path.length-1];if(X===Y||adj.get(X).has(Y)||new Set(path).size<path.length)return;
    let d=0;for(let i=1;i<path.length;i++)d+=km(path[i-1],path[i]);const dd=km(X,Y);if(d>dd*1.45+800)return;
    const k=X<Y?X+">"+Y:Y+">"+X,o=best.get(k);if(o&&(o.path.length<path.length||(o.path.length===path.length&&o.km<=d)))return;best.set(k,{path,km:d,dd})};
  for(const h of H){const N=adj.get(h);if(!N)continue;const ns=[...N.keys()];
    for(let i=0;i<ns.length;i++)for(let j=i+1;j<ns.length;j++)consider([ns[i],h,ns[j]]);
    for(const h2 of H){if(h2===h||!N.has(h2))continue;for(const X of ns)if(X!==h2)for(const Y of adj.get(h2).keys())if(Y!==h)consider([X,h,h2,Y])}}
  const its=[];
  for(const it of best.values()){const n=it.path.length-1,rs=[];let hb=1;for(let i=1;i<n;i++)hb*=pBoost(it.path[i]);
    for(let i=1;i<=n;i++)rs.push(adj.get(it.path[i-1]).get(it.path[i]));
    its.push({kind:"sea",path:it.path,dem:seaOwn(port(it.path[0]),port(it.path[n]),it.dd)*XS_TEU[n]*hb,dd:it.dd,km:it.km,rs})}
  const raw=new Map();for(const it of its)for(const l of it.rs)raw.set(l,(raw.get(l)||0)+it.dem);
  const ratio=new Map();for(const [l,v] of raw)ratio.set(l,Math.min(1,XS_CAP*seaOwn(port(l.from),port(l.to),km(l.from,l.to))/v));
  for(const it of its){it.dem*=Math.min(...it.rs.map(l=>ratio.get(l)));it.rs=it.rs.map(l=>l.id);if(it.dem<.5)continue;
    for(const id of it.rs)out.leg.set(id,(out.leg.get(id)||0)+it.dem);out.its.push(it)}
  out.its.sort((a,b)=>b.dem-a.dem);xsCache=out;return out}
const xsOf=l=>l.id>0?(seaNet().leg.get(l.id)||0):0;
function laneCalc(l){const a=port(l.from),b=port(l.to),sp=seaPath(l.from,l.to),km=sp.km,ev=evShip(l.from)*evShip(l.to);
  const XS=xsOf(l),D=seaOwn(a,b,km)*ev*pBoost(l.from)*pBoost(l.to)*dealCargo()+XS,Dr=skOpen("r")?D*.22:0,Do=skOpen("o")?D*.3:0;
  const DK={d:D,r:Dr,o:Do};laneAutoAssign(l,DK,km);
  const capK={d:0,r:0,o:0};let fixed=0;
  for(const id of l.ships){const sh=shipById(id);if(!sh)continue;const m=shipM(sh.m);fixed+=m.price*.0004;if(sh.down>S.day)continue;const k=shipK(sh,m);capK[k]+=m.teu*shipLoadF(m,k)/legDaysS(m,km)}
  // with "wait for cargo" ships stay in port until they are w full: they sail a fraction sK of their schedule, each sailing w full
  const w=l.wait||0,loadK={},sK={};
  for(const k of ["d","r","o"]){const ld0=capK[k]?Math.min(1,DK[k]/capK[k]):0;if(w>0&&ld0>0&&ld0<w){sK[k]=ld0/w;loadK[k]=w}else{sK[k]=1;loadK[k]=ld0}}
  let rev=0,fuel=0,fee=0,teu=0,spoil=0,saved=0;
  for(const id of l.ships){const sh=shipById(id);if(!sh||sh.down>S.day)continue;const m=shipM(sh.m),Ld=legDaysS(m,km),k=shipK(sh,m),f=shipLoadF(m,k),ld=loadK[k],sf=sK[k];
    const sp=(k==="r"&&!shipSpec(m)?SPOIL:0)*(1-sf)+LATE*(1-sf),rv=m.teu*f*ld*sf*TEU_RATE(km)*SEA_RATE[k]*specX(m)*pk("cargo")/Ld;
    teu+=m.teu*f*ld*sf/Ld;rev+=rv*(1-sp);spoil+=rv*sp;const fl=km*m.cpk*fuelNow()*pk("fuel")/Ld,fe=(portFee(a,m)+portFee(b,m))/2/Ld;fuel+=fl*sf;fee+=fe*sf;saved+=(fl+fe)*(1-sf)}
  return {sp,km,XS,xteu:D>0?teu*XS/D:0,D,Dr,Do,DK,capK,loadK,sK,spoil,saved,w,cap:capK.d,capr:capK.r,capo:capK.o,load:loadK.d,loadr:loadK.r,loado:loadK.o,teu,rev,fuel,fee,fixed,profit:rev-fuel-fee-fixed}}
const shipRateX=m=>m.reefer?1.8:m.roro?1.5:1;
const shipType=m=>m.reefer?"reefer":m.roro?"roro":"box";
const SCATS=[["all",_T("ทั้งหมด")],["box",_T("📦 ตู้คอนเทนเนอร์")],["reefer",_T("❄ ห้องเย็น")],["roro",_T("🚗 ขนรถ")]];
// Each ship is paid when it arrives: freight − fuel − port call fee
function settleShips(T){
  for(const l of S.lanes){let lc=null;syncLaneSpread(l);
    for(const id of l.ships){const sh=shipById(id);if(!sh)continue;const m=shipM(sh.m);lc=lc||laneCalc(l);
      const Ld=legDaysS(m,lc.km),sail=sailDays(m,lc.km)/Ld,key=l.id+":"+lc.km,N=Math.floor(T/Ld+(sh.off||0)-sail);
      if(sh.lk!==key){sh.lk=key;sh.ld=N;continue}
      if(N<=sh.ld)continue;const n0=sh.ld;sh.ld=N;if(sh.down>S.day)continue;
      for(let n=Math.max(n0+1,N-3);n<=N;n++)sailLeg(l,sh,m,lc,n)}}}
function sailLeg(l,sh,m,lc,n){const bkk=shipK(sh,m),sf=lc.sK?lc.sK[bkk]:1;
  if(sf<1){sh.wacc=(sh.wacc||0)+sf;if(sh.wacc<1-1e-9){sh.waiting=1;sh.wport=n%2===1?l.to:l.from;return}sh.wacc-=1}sh.waiting=0;   // still waiting for cargo in port
  const f=shipLoadF(m,bkk),ld=lc.loadK[bkk],arr=port(n%2===1?l.from:l.to),capT=m.teu*f;let teu=capT*ld*(.9+Math.random()*.2);
  if(l.bk&&l.bk[bkk]>0&&teu<capT){const tk=Math.min(capT-teu,l.bk[bkk]);l.bk[bkk]-=tk;teu+=tk}
  const o={srev:teu*TEU_RATE(lc.km)*SEA_RATE[bkk]*specX(m)*pk("cargo")*(1-((bkk==="r"&&!shipSpec(m)?SPOIL:0)+LATE)*(1-sf)),sfuel:lc.km*m.cpk*fuelNow()*pk("fuel"),sport:portFee(arr,m),teu,voy:1};
  const net=o.srev-o.sfuel-o.sport;S.cash+=net;sh.tn=(sh.tn||0)+net;addT(S.today,o);l.today=l.today||{};addT(l.today,o);S.totTeu=(S.totTeu||0)+teu;
  if(PREF.floats&&(tab==="home"||tab==="map")&&vmode()!=="air"&&floaters.length<14)floaters.push({p:arr.c,v:net,t0:performance.now()})}
function shipResale(sh){return shipM(sh.m).price*.6*Math.max(.5,1-sh.age/7300)}
function shipFixed(){return S.ships.reduce((a,sh)=>a+shipM(sh.m).price*(sh.lane?.0004:.0002)*upkeepK(shipM(sh.m)),0)}
function buyShip(id){const m=shipM(id);if(S.cash<m.price)return null;S.cash-=m.price;
  const sh={id:S.nid++,m:id,reg:`${S.code}-M${String(S.ships.length+1).padStart(2,"0")}`,lane:null,off:Math.random(),age:0,down:0};
  S.ships.push(sh);buzz(18);addNews(_T`🚢 รับมอบ${m.name} ชื่อ ${sh.reg}`);toast(_T`ซื้อ${m.name}แล้ว`);save();return sh}
const laneAvg=l=>l.h&&l.h.length>=3?l.h.reduce((a,x)=>a+x,0)/l.h.length:laneCalc(l).profit;
const pbl=c=>(S.pbr&&S.pbr[c])||0;
const pbList=()=>Object.keys(S.pbr||{});
function pBranchCost(c){const pt=port(c);return Math.round((40e6+pt.w*10e6)*(1+.3*pbList().length)/5e6)*5e6}
function pBranchUp(c){const pt=port(c);return Math.round((25e6+pt.w*8e6)*pbl(c)/5e6)*5e6}
function pBranchUpkeep(c){const pt=port(c);return (120e3+pt.w*20e3)*pbl(c)}
const pBoost=c=>1+.08*Math.max(0,pbl(c)-1);
function openPortBranch(code){const pt=port(code),cost=pBranchCost(code);if(S.cash<cost||!portOpen(code)||pbl(code))return false;
  S.cash-=cost;S.pbr[code]=1;addNews(_T`⚓ เปิดสาขาท่าเรือที่${pt.n} เปิดเส้นทางเรือออกจากที่นี่ได้แล้ว`);celebrate(_T("สาขาท่าเรือใหม่"),pt.n);save();return true}
const laneNo=l=>`S${String(S.lanes.indexOf(l)+1).padStart(2,"0")}`;

const isOpen=c=>S.unlocked.includes(regionOf(c).id);
function regionCost(R){const hub=city(S.hub);const d=Math.min(...R.c.map(c=>dist(hub,city(c))));return Math.round((20e6+d*22e3)/5e6)*5e6}
