const verNum=v=>v.split(".").map(Number).reduce((a,x)=>a*1000+x,0);
let updAvail=null;
function checkUpdate(manual){if(!/^https?:/.test(location.protocol)){if(manual)toast(_T("ตรวจอัปเดตได้เฉพาะตอนเล่นบนเว็บ"));return Promise.resolve(null)}
  return fetch("version.json?t="+Date.now(),{cache:"no-store"}).then(r=>r.ok?r.json():null).then(j=>{
    if(j&&j.v&&verNum(j.v)>verNum(GAME_VERSION)){updAvail=j.v;showUpdBar()}else if(manual)toast(_T`เป็นเวอร์ชันล่าสุดแล้ว (v${GAME_VERSION})`);return j}).catch(()=>{if(manual)toast(_T("ตรวจอัปเดตไม่ได้ ลองใหม่เมื่อต่อเน็ต"));return null})}
function showUpdBar(){if(!updAvail||document.getElementById("updbar"))return;const b=document.createElement("button");b.id="updbar";b.className="updbar";
  b.innerHTML=_T`🔄 มีอัปเดตใหม่ v${updAvail} (ตอนนี้ v${GAME_VERSION}) · <b>แตะเพื่อโหลด</b> เกมบันทึกไว้แล้ว`;b.onclick=loadUpdate;document.body.appendChild(b)}
function loadUpdate(){try{if(S)save()}catch(e){}
  // a fresh address skips a cached copy of the page itself
  const go=()=>location.replace(location.pathname+"?u="+encodeURIComponent(updAvail||GAME_VERSION)+location.hash);
  if(navigator.serviceWorker&&navigator.serviceWorker.getRegistration)navigator.serviceWorker.getRegistration().then(r=>r?r.update().catch(()=>{}).then(go):go()).catch(go);else go()}
// after an update has been loaded: say so once, with what changed since the version played before
function afterUpdate(){let last=null;try{last=localStorage.getItem("airline-ver")}catch(e){}
  try{localStorage.setItem("airline-ver",GAME_VERSION)}catch(e){}
  if(!last||last===GAME_VERSION||!S)return;const news=CHANGELOG.filter(([v])=>verNum(v)>verNum(last));if(!news.length)return;
  setTimeout(()=>openSheet(changelogSheet(last)),900)}
function changelogSheet(from){const fn=()=>{let h=head(from?_T`🎉 อัปเดตเป็น v${GAME_VERSION} แล้ว`:_T`ℹ️ เวอร์ชัน v${GAME_VERSION}`,from?_T`จากเวอร์ชัน v${from} ที่เล่นครั้งก่อน`:_T("เวอร์ชันที่เล่นอยู่ และมีอะไรใหม่"));
   h+=_T`<div class="panel row between"><span>เวอร์ชันที่เล่นอยู่ <b class="num">v${GAME_VERSION}</b>${updAvail?_T` · <span class="warn">มีใหม่ v${updAvail}</span>`:""}</span>${updAvail?_T`<button class="btn sm primary" id="updnow">โหลดอัปเดต</button>`:_T`<button class="btn sm" id="updchk">ตรวจหาอัปเดต</button>`}</div>`;
   h+=CHANGELOG.map(([v,d,items])=>`<div class="panel stack chlog ${from&&verNum(v)>verNum(from)?"new":""}"><div class="row between"><b>v${v}${v===GAME_VERSION?_T(" · ตอนนี้"):""}${from&&verNum(v)>verNum(from)?_T(' <span class="chip got">ใหม่</span>'):""}</b><span class="muted small">${d}</span></div><ul class="small">${items.map(t=>`<li>${t}</li>`).join("")}</ul></div>`).join("");
   h+=_T`<div class="muted small">ถ้าเห็นหน้าตาแปลก ๆ หลังอัปเดต ให้รีโหลดหน้าเว็บอีกครั้ง · เกมบันทึกอัตโนมัติ อัปเดตแล้วเซฟไม่หาย</div>`;return h};
 fn.bind=()=>{const c=$("#updchk");if(c)c.onclick=()=>checkUpdate(true).then(()=>drawSheet());const u=$("#updnow");if(u)u.onclick=loadUpdate};return fn}
let CARGO_RATE=8;const cgRate=d=>CARGO_RATE*(1500+.85*d);/* baht per tonne at rate 1.0 */const KEY="airline-owner-v1", START=new Date(2027,0,1), DAY_MS=30000, SPEEDS=[1,3,10,30];

const $=s=>document.querySelector(s);
const $$=s=>document.querySelectorAll(s);
const city=c=>_city(CITIES,c);
const model=id=>_model(MODELS,id);
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rnd=a=>a[Math.floor(Math.random()*a.length)];
/* ⚙️ Device preferences (this browser only, not part of the save): display, notifications, sound, game start.
   Settings that belong to one airline (auto maintenance, rivals, haptics, pop-ups of unlocks) live in S. */
const PREF_DEF={font:"m",motion:"auto",toast:"all",fx:true,floats:true,sound:true,vol:.5,speed0:1,daily:"popup",away:"popup",news:{},mapfps:"auto",lagGuard:true};
let PREF=(()=>{try{return Object.assign({},PREF_DEF,JSON.parse(localStorage.getItem("airline-prefs")||"{}"))}catch(e){return {...PREF_DEF}}})();
const savePref=()=>{try{localStorage.setItem("airline-prefs",JSON.stringify(PREF))}catch(e){}};
let reduce=false;
function applyPrefs(){reduce=PREF.motion==="less"||(PREF.motion==="auto"&&matchMedia("(prefers-reduced-motion: reduce)").matches);
  document.documentElement.classList.toggle("lessmotion",reduce);
  const z={s:.9,m:1,l:1.1,xl:1.22}[PREF.font]||1;for(const id of ["app","toast"]){const el=document.getElementById(id);if(el)el.style.zoom=z===1?"":String(z)}}
applyPrefs();
/* sounds: small synthesised blips (no files to load), only after the player has touched the page */
let AC=null;
function sfx(k){if(!PREF.sound||!(PREF.vol>0))return;try{AC=AC||new (window.AudioContext||window.webkitAudioContext)();if(AC.state==="suspended")AC.resume();
  const N={tap:[[660,.05]],note:[[880,.07],[1320,.1]],buy:[[523,.06],[784,.06],[1047,.12]],win:[[523,.09],[659,.09],[784,.09],[1047,.25]],cash:[[1568,.05],[2093,.09]],bad:[[247,.14],[196,.22]]}[k]||[[660,.05]];
  let t=AC.currentTime+.01;for(const [f,d] of N){const o=AC.createOscillator(),g=AC.createGain();o.type="triangle";o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.16*PREF.vol,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(AC.destination);o.start(t);o.stop(t+d+.03);t+=d*.8}}catch(e){}}
let lastInput=0;addEventListener("pointerdown",()=>{lastInput=performance.now()},true);addEventListener("keydown",()=>{lastInput=performance.now()},true);
function dist(a,b){const R=6371,r=Math.PI/180,dl=(b.lat-a.lat)*r,dn=(b.lon-a.lon)*r;
  const h=Math.sin(dl/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dn/2)**2;return Math.round(2*R*Math.asin(Math.sqrt(h)))}
const rd=r=>dist(city(r.from),city(r.dest));
/* economy dial: scales every ticket fare and freight rate (tuned so a good route pays back its aircraft in about a year) */
let FARE_X=.8;   // freight rate CARGO_RATE (8.0) is scaled by the same 0.8
// fares rise almost in step with distance, as real one-way economy fares do (long-haul ~฿20k+)
const baseFare=d=>Math.round(FARE_X*(1300+2.0*d)/10)*10;
/* A real aircraft day: turboprops fly ~15 h with 25-min turns, narrow-bodies ~17-18 h with 45-min turns,
   wide-bodies and big freighters up to 20 h but need ~1.8 h on the ground (cleaning, catering, loading).
   Block time = flight time + ~30 min taxi/climb/approach. */
const acClass=m=>m.cat==="wide"||(!m.seats&&m.cargo>=50)?"wide":m.speed<600?"prop":"narrow";
const OPS={prop:{op:15,turn:.45},narrow:{op:17.5,turn:.75},wide:{op:20,turn:1.8}};
const legsFor=(m,d)=>{const o=OPS[acClass(m)];return clamp(Math.floor(o.op/(d/m.speed+.5+o.turn)),1,12)};
// planes take longer in the air on screen; the time comes out of ground time, so the number of flights per day stays the same
