// a rival's home base and fleet, for flavour and for the news
function rvHub(rv){if(!rv.hub){const big=CITIES.filter(c=>c.w>=8&&c.c!==S.hub&&!S.rivals.some(x=>x.hub===c.c));rv.hub=(big[(rv.n.length*7+S.rivals.indexOf(rv)*13)%Math.max(1,big.length)]||CITIES[0]).c}return rv.hub}
const rvFleet=rv=>{const m=rvOps(rv);return {air:Math.max(2,Math.round(m.pax/900+m.cargo/80)),sea:Math.round(m.sea/220)}};
function rvNews(rv,a,b){if(!has("rank")||(rv.newsCool||0)>S.day)return;const fa=Math.round(a.pax/900+a.cargo/80),fb=Math.round(b.pax/900+b.cargo/80),sa=Math.round(a.sea/220),sb=Math.round(b.sea/220);
  let t=null;const hub=city(rvHub(rv));
  if(Math.floor(b.net)>Math.floor(a.net)&&Math.random()<.5){const cand=CITIES.filter(c=>c.c!==hub.c&&c.w>=3);const c=cand[(Math.floor(b.net)*31+rv.n.length)%cand.length];t=_T`✈️ ${rv.n} เปิดเส้นทางใหม่ ${hub.n} – ${c.n}`}
  else if(fb>=fa+2)t=_T`🛬 ${rv.n} รับเครื่องบินใหม่ ${fb-fa} ลำ (ฝูงบินรวม ${fb} ลำ)`;
  else if(sb>sa&&b.sea>0)t=_T`🚢 ${rv.n} รับเรือใหม่ (กองเรือรวม ${sb} ลำ)`;
  if(t){addNews(t);rv.newsCool=S.day+20+Math.floor(Math.random()*15)}}
function rvCat(rv,k){if(k==="val")return rv.v;if(k==="svc")return rivalStars(rv);if(!["pax","cargo","sea","net"].includes(k))return rivalScore(rv);
  const m=rvOps(rv);if(k==="net")return Math.round(m.net);
  return m[k]*(1+.06*Math.sin(S.day/23+rv.n.length))}   // busy and quiet weeks
function catBoard(k){return [...S.rivals.map(rv=>({n:rv.n,v:rvCat(rv,k),rv})),{n:S.name,v:myCat(k),me:1}].sort((a,b)=>b.v-a.v)}
const catRank=k=>catBoard(k).findIndex(x=>x.me)+1;
const catFmt=(k,v)=>k==="val"?money(v,true):k==="svc"?v.toFixed(1):Math.round(v).toLocaleString();
const medal=r=>r===1?"🥇":r===2?"🥈":r===3?"🥉":"#"+r;
function armsNews(){if(!has("super"))return;const k=Math.round((armsK()-1)*100),was=S.armsSeen||0;if(k>=was+10){S.armsSeen=k-k%10;addNews(_T`⚔️ คู่แข่งเร่งสร้างฝูงบินตอบโต้ฝูงพิเศษของเรา ตั้งเป้าสูงขึ้น +${k}%`)}}
function catTick(){armsNews();const L=S.last||{},e=(o,x)=>o==null?x:o+(x-o)*.2;S.cat=S.cat||{};
  S.cat.pax=e(S.cat.pax,L.pax||0);S.cat.cargo=e(S.cat.cargo,L.cargo||0);S.cat.teu=e(S.cat.teu,L.teu||0);
  rvOpsTick();
  // service-minded rivals drift toward their own level of service
  for(const rv of S.rivals){const P=rvProf(rv);rv.st=clamp(rivalStars(rv)+(P.st-rivalStars(rv))*.03,2.5,4.9)}
  if(!has("rank"))return;S.catTop=S.catTop||{};
  for(const c of catList()){if(c.k==="all")continue;const B=catBoard(c.k),top=B[0],was=S.catTop[c.k];if(top.n===was)continue;S.catTop[c.k]=top.n;if(was==null)continue;
    if(top.me){addNews(_T`${c.e} เราขึ้นอันดับ 1 ด้าน${c.n}แล้ว!`);celebrate(_T("!🥇 อันดับ 1 ด้าน")+c.n,`${catFmt(c.k,top.v)} ${c.u}`)}
    else if(was===S.name)addNews(_T`${c.e} ${top.n} แย่งอันดับ 1 ด้าน${c.n}ไปจากเรา`)}}
// the tightest race involving us: someone right behind us, or someone we are about to pass
function closestRace(){let best=null;for(const c of catList()){if(c.k==="all"||c.k==="svc")continue;const B=catBoard(c.k),i=B.findIndex(x=>x.me),me=B[i];if(!me||me.v<=0)continue;
    for(const j of [i-1,i+1]){const o=B[j];if(!o)continue;const gap=Math.abs(o.v-me.v)/Math.max(o.v,me.v);if(!best||gap<best.gap)best={gap,c,o,ahead:j<i}}}
  if(!best||best.gap>.15)return null;const {c,o,ahead,gap}=best,pc=Math.max(1,Math.round(gap*100));
  return ahead?{t:_T`ใกล้แซง ${o.n} ด้าน${c.n}`,d:_T`ห่างแค่ ${pc}% ขึ้นอันดับ ${catRank(c.k)-1} ได้`}:{t:_T`${o.n} ไล่จี้ด้าน${c.n}`,d:_T`ตามเราอยู่แค่ ${pc}% · ระวังเสียอันดับ ${catRank(c.k)}`}}
const rvLine=n=>{const rv=S.rivals.find(x=>x.n===n);if(!rv)return "";const f=rvFleet(rv);return _T`<br><span class="muted" style="font-size:11.5px">ฐาน ${city(rvHub(rv)).n} · ✈ ${f.air} ลำ${f.sea?_T` · 🚢 ${f.sea} ลำ`:""} · ${Math.round(rvOps(rv).net)} จุดหมาย</span>`};
let catSeg="all";
function catHTML(board){const L=catList(),k=L.some(c=>c.k===catSeg)?catSeg:"all",C=RACES.find(c=>c.k===k);
  const chips=`<div class="catchips">${L.map(c=>`<button data-race="${c.k}" class="${c.k===k?"on":""}">${c.e} ${c.n}<small>${medal(c.k==="all"?rank():catRank(c.k))}</small></button>`).join("")}</div>`;
  const rows=k==="all"?board.map(b=>({n:b.n,me:b.me,st:b.st,txt:_T`${b.sc.toLocaleString()}<span class="muted small"> คะแนน</span>`}))
    :catBoard(k).map(b=>({n:b.n,me:b.me,st:b.me?(S.rating?S.rating.overall:0):rivalStars(b.rv),txt:`${catFmt(k,b.v)}${k==="val"?"":`<span class="muted small"> ${C.u}</span>`}`}));
  const note=k==="all"?_T("อันดับรวมจากขนาดบริษัท · กดหมวดด้านบนเพื่อดูการแข่งขันแต่ละด้าน คู่แข่งแต่ละเจ้าเก่งไม่เหมือนกัน"):
    k==="val"?_T("มูลค่ากิจการ = เงินสด + มูลค่าฝูงบินและกองเรือ − เงินกู้"):k==="net"?_T("จำนวนเมืองและท่าเรือที่เรามีเที่ยวบินหรือเรือไปถึง · เปิดเส้นทางใหม่เพื่อไต่อันดับ"):k==="svc"?_T("เรตติ้งเฉลี่ยจากผู้โดยสาร (ความตรงเวลา บริการ สภาพเครื่อง)"):
    _T`ค่าเฉลี่ยต่อวันช่วงหลัง · ${k==="pax"?_T("เพิ่มเครื่องและเส้นทางผู้โดยสาร"):k==="cargo"?_T("เพิ่มเครื่องบินขนสินค้าและเส้นทางสินค้า"):_T("เพิ่มเรือและเส้นทางเดินเรือ")}เพื่อไต่อันดับด้านนี้`;
  return _T`<div class="panel"><div class="eyebrow" style="margin-bottom:6px">📋 ตารางอันดับ</div>${chips}<div class="small muted" style="margin:6px 0">${note}</div>
    <div class="board">${rows.map((b,i)=>`<div class="r ${b.me?"me":""}"><span class="num muted">${i<3?medal(i+1):"#"+(i+1)}</span><span class="nm" style="min-width:0">${esc(b.n)}<br>${starsHTML(b.st||0,11)} <span class="num muted" style="font-size:11px">${(b.st||0).toFixed(1)}</span>${b.me?"":_T` <span class="stance">เด่น ${rvProf(S.rivals.find(x=>x.n===b.n)).tag}</span>`+(k==="all"?rvStance(b.n):"")+rvLine(b.n)}</span><span class="num">${b.txt}</span></div>`).join("")}</div></div>`}
// tell the player when the order in the table changes (rate-limited so small back-and-forth isn't spam)
function rankNews(){if(!has("rank"))return;const B=standings().map(x=>x.n),prev=S.lastOrder;S.lastOrder=B;if(!prev)return;
  for(let i=0;i<B.length;i++){const n=B[i],j=prev.indexOf(n);if(j>i&&n!==S.name&&i<prev.length&&prev[i]!==n){const passed=prev[i];
    if(passed===S.name){if((S.rnMe||0)<=S.day){S.rnMe=S.day+5;addNews(_T`⚠️ ${n} แซงเราขึ้นเป็นอันดับ ${i+1}`)}}
    else if(i<3&&(S.rnCool||0)<=S.day){S.rnCool=S.day+7;addNews(_T`🔀 ${n} แซง ${passed} ขึ้นเป็นอันดับ ${i+1}`)}}}}
function randomEvent(){
  if(Math.random()>.07)return;
  const served=[...S.bases,...S.routes.map(r=>r.dest)];
  const c=city(Math.random()<.7?rnd(served):rnd(CITIES.filter(x=>isOpen(x.c))).c);
  const k=Math.random();
  if(k<.15){S.fuel=clamp(S.fuel*1.22,.6,1.9);addNews(_T`⛽ ราคาน้ำมันพุ่งขึ้นกะทันหัน ดัชนีอยู่ที่ ${S.fuel.toFixed(2)}${S.hedge?_T(" แต่คุณล็อกราคาไว้แล้ว"):""}`)}
  else if(k<.26){S.fuel=clamp(S.fuel*.85,.6,1.9);addNews(_T`⛽ ราคาน้ำมันร่วง ดัชนีอยู่ที่ ${S.fuel.toFixed(2)}`)}
  else if(k<.45){S.events.push({type:"fest",city:c.c,mult:1.6,until:S.day+7});addNews(_T`🎉 เทศกาลใหญ่ที่${c.n} คนและสินค้าเดินทางเพิ่ม 60% อีก 7 วัน`)}
  else if(k<.59){S.events.push({type:"storm",city:c.c,until:S.day+2});addNews(_T`🌀 พายุเข้า${c.n} ทุกเที่ยวบินเข้า-ออกงดบิน 2 วัน`)}
  else if(k<.75){S.events.push({type:"comp",city:c.c,mult:.75,until:S.day+30});addNews(_T`✈️ ${rnd(S.rivals).n} เปิดเส้นทางไป${c.n} ความต้องการลดลง 25% อีก 30 วัน`)}
  else if(k<.84){S.rep=clamp(S.rep+6,0,100);addNews(_T`📣 คลิปลูกเรือ ${S.name} เป็นไวรัล ชื่อเสียงเพิ่มขึ้น`)}
  else if(k<.88&&S.lanes.length&&Math.random()<.5){if(Math.random()<.35&&!suezShut()){S.events.push({type:"suez",until:S.day+8});seaCache.clear();addNews(_T("🚢 เรือสินค้าเกยตื้นในคลองสุเอซ ปิดคลอง 8 วัน เรือต้องอ้อมแหลมกู๊ดโฮป"))}
    else{const pl=port(rnd(S.lanes.flatMap(l=>[l.from,l.to])));S.events.push({type:"strike",port:pl.c,pmult:.3,until:S.day+4});addNews(_T`⚓ แรงงานท่าเรือ${pl.n}นัดหยุดงาน 4 วัน ตู้สินค้าลดลง 70%`)}}
  else if(k<.88){const cc=city(rnd(served));S.events.push({type:"cboost",city:cc.c,cmult:1.6,until:S.day+10});addNews(_T`📦 ความต้องการส่งยาและอุปกรณ์การแพทย์ทางอากาศที่${cc.n}เพิ่ม 60% อีก 10 วัน`)}
  else if(k<.92){const rv=rnd(S.rivals);rv.v*=.9;addNews(_T`📉 ${rv.n} เจอปัญหาการเงิน มูลค่าลดลง 10%`)}
  else if(S.fleet.length){const p=rnd(S.fleet);p.down=S.day+3;const cost=model(p.m).price*.004;S.cash-=cost;addNews(_T`🔧 ${p.reg} นกชนเครื่องยนต์ ต้องซ่อม 3 วัน เสีย ${money(cost)}`)}
}

/* ---------- effects ---------- */
const buzz=ms=>{sfx(Array.isArray(ms)?"win":"buy");try{if(S&&S.haptic!==false&&navigator.vibrate)navigator.vibrate(ms)}catch(e){}};
function toast(t){const mine=performance.now()-lastInput<2500;   // a reply to what the player just did, or news the game announces by itself
  if(PREF.toast==="off"||(PREF.toast==="mine"&&!mine))return;if(!mine)sfx("note");const el=$("#toast");el.hidden=true;void el.offsetWidth;el.textContent=t;el.hidden=false;clearTimeout(toast.h);toast.h=setTimeout(()=>el.hidden=true,3200)}
function floatCash(n){const host=$(".cash");if(!host||reduce||!PREF.floats)return;const now=performance.now();if(now-lastFloat<500)return;lastFloat=now;
  const f=document.createElement("span");f.className="float "+(n>=0?"good":"bad");f.textContent=(n>=0?"+":"")+money(n,true);host.appendChild(f);setTimeout(()=>f.remove(),1150)}
const cel=[];
let celBusy=false,celWait=0;
const updCelBtn=()=>{const l=$("#cellbl");if(l&&S)l.textContent=S.celOff?_T("ป๊อปอัปปลดล็อก: ปิดอยู่ · แตะเพื่อเปิด"):_T("ป๊อปอัปปลดล็อก: เปิดอยู่ · แตะเพื่อปิด")};
function celebrate(k,t){if(afk){afk.log.unshift(`🏅 ${k}: ${t}`);return}if(S&&S.celOff)return;   // player turned the pop-ups off (news still records them)
  cel.push([k,t]);
  if(!celBusy){clearTimeout(celWait);celWait=setTimeout(nextCel,350)}}   // wait a moment so things unlocked together show as one card
function nextCel(){if(!cel.length){celBusy=false;return}celBusy=true;buzz([25,50,25]);
  const seen=new Set(),batch=cel.splice(0,6).filter(([k,t])=>!seen.has(k+t)&&seen.add(k+t)).slice(0,4),lab=k=>k.startsWith("!")?k.slice(1):_T("ปลดล็อก")+k,short=k=>k.startsWith("!")?k.slice(1).replace(/[!]/g,""):k;
  const d=document.createElement("div");d.className="unlock"+(batch.length>1?" multi":"");
  d.innerHTML=batch.length===1?`<div class="eyebrow">${esc(lab(batch[0][0]))}</div><b>${esc(batch[0][1])}</b>`
    :_T`<div class="eyebrow">🎉 ปลดล็อก ${batch.length} อย่าง</div><ul>${batch.map(([k,t])=>`<li><b>${esc(t)}</b><span class="muted">${esc(short(k))}</span></li>`).join("")}</ul>`;
  document.body.appendChild(d);confetti(innerWidth/2,innerHeight*.16);
  d.insertAdjacentHTML("beforeend",_T`<button class="celoff" type="button">ไม่ต้องแสดงป๊อปอัปแบบนี้อีก</button>`);
  const done=()=>{if(!d.isConnected)return;d.remove();nextCel()};d.onclick=done;
  d.querySelector(".celoff").onclick=e=>{e.stopPropagation();S.celOff=true;cel.length=0;save();d.remove();celBusy=false;toast(_T("ปิดป๊อปอัปปลดล็อกแล้ว · เปิดใหม่ได้ที่ ⋯ → ⚙️ ตั้งค่า"));updCelBtn()};
  setTimeout(done,reduce?1800:batch.length>1?3600:2600)}
function flyover(){if(reduce||!PREF.fx)return;const d=document.createElement("div");d.className="flyover";if(S)d.style.color=S.livery.tail;
  d.innerHTML=`<svg viewBox="0 0 84 40"><defs><linearGradient id="tr" x1="0" x2="1"><stop offset="0" stop-color="currentColor" stop-opacity="0"/><stop offset="1" stop-color="currentColor" stop-opacity=".5"/></linearGradient></defs><rect x="0" y="19" width="44" height="2" rx="1" fill="url(#tr)"/><path fill="currentColor" d="M44 20l10-3 4-12h4l-2 11 14-3c3-.5 6 0 8 1.5v1c-2 1.5-5 2-8 1.5l-14-3 2 11h-4l-4-12-10-3z" transform="translate(0,4) scale(1,.8)"/></svg>`;
  document.body.appendChild(d);setTimeout(()=>d.remove(),2000)}

