const secHead=(e,t,sub)=>`<div class="sec"><span class="sec-e">${e}</span><h3>${t}</h3>${sub?`<span class="muted small">${sub}</span>`:""}</div>`;
/* What people say about the airline: passengers, shippers, crew and the press, each about one thing, from the real numbers */
