function buyPlanShips(l,v){let k=0;for(const part of v.split("|")){const [mid,ck,n]=part.split(":");for(let i=0;i<+n;i++){const sh=buyShip(mid);if(!sh)break;applyCk(sh,ck||"auto",shipSpec(shipM(sh.m)));l.ships.push(sh.id);sh.lane=l.id;k++}}save();toast(_T`ซื้อเรือ ${k} ลำ เข้าประจำ ${laneNo(l)} แล้ว`)}
