  if(rsvOut.length)h+=_T`<div class="fsec rsv"><b>🛟 สำรอง · กำลังช่วยงาน/เดินทาง ${rsvOut.length} ลำ</b><span class="small muted">ถูกส่งไปบินเส้นที่ล้น · จะบินกลับฐานเองเมื่อที่นั่ง/ระวางพอ ${RSV_BACK} วันติด</span></div>${wrap(rsvOut)}`;
