    const ro=$("#rsvoff");if(ro)ro.onclick=()=>{delete p.reserve;delete p.fer;save();toast(_T`${p.reg} เลิกเป็นเครื่องสำรองแล้ว${p.route?_T(" (ยังบินเส้นเดิมต่อ)"):""}`);drawSheet()};
