/* 💬 Feedback to the developer: sent to /api/feedback (Cloudflare Worker + D1). Only the message, its kind, the game
   version, the game day and a short device type are sent; no name, e-mail or save. The server masks rude words,
   limits how often one connection can send and drops exact repeats. */
const FB_CATS=[["bug",_T("🐞 แจ้งบัค")],["idea",_T("💡 ไอเดีย / ขอฟีเจอร์")],["balance",_T("⚖️ ความสมดุลของเกม")],["other",_T("💬 อื่น ๆ")]];
const devKind=()=>{const u=navigator.userAgent;return (/iPad|Tablet/i.test(u)||(/Macintosh/.test(u)&&navigator.maxTouchPoints>1)?_T("แท็บเล็ต"):/Mobi|Android|iPhone/i.test(u)?_T("มือถือ"):_T("คอม"))+" "+innerWidth+"px"};
function feedbackSheet(st){st=st||{cat:"idea",msg:""};const fn=()=>head(_T("💬 ส่งความเห็นถึงผู้พัฒนา"),_T("เจอบัค อยากได้อะไรเพิ่ม หรือคิดว่าตรงไหนง่าย/ยากเกินไป บอกได้เลย ผู้พัฒนาอ่านทุกข้อความ"))+
  (st.sent?_T`<div class="panel stack" style="text-align:center"><div style="font-size:40px">🙏</div><b>ส่งแล้ว ขอบคุณมากครับ</b><div class="small muted">ความเห็นของคุณช่วยให้เกมดีขึ้น</div><button class="btn" id="fbmore">ส่งอีกเรื่อง</button></div>`:
  _T`<div class="seg setseg" style="flex-wrap:wrap">${FB_CATS.map(([k,n])=>`<button type="button" data-fbc="${k}" class="${st.cat===k?"on":""}">${n}</button>`).join("")}</div>
   <textarea id="fbmsg" rows="6" maxlength="1000" placeholder="${st.cat==="bug"?_T("เกิดอะไรขึ้น ทำอะไรอยู่ตอนนั้น และคาดว่าควรเป็นแบบไหน"):_T("เขียนได้เต็มที่ ไม่เกิน 1,000 ตัวอักษร")}" style="width:100%;font-size:15px">${esc(st.msg)}</textarea>
   <input type="text" id="fbhp" tabindex="-1" autocomplete="off" aria-hidden="true" style="position:absolute;left:-9999px;width:1px;height:1px">
   <div class="row between small muted"><span>แนบให้อัตโนมัติ: v${GAME_VERSION}${S?_T` · วันที่ ${S.day} ในเกม`:""} · ${esc(devKind())}</span><span id="fbn">${st.msg.length}/1000</span></div>
   ${st.err?`<div class="small bad">⚠️ ${esc(st.err)}</div>`:""}
   <button class="btn primary" id="fbsend" ${st.busy?"disabled":""}>${st.busy?_T("กำลังส่ง…"):_T("ส่งความเห็น")}</button>
   <div class="small muted">ไม่เก็บชื่อ อีเมล หรือเซฟของคุณ · ข้อความหยาบจะถูกปิดด้วย * ก่อนบันทึก · ส่งได้ไม่เกิน 5 ครั้งต่อชั่วโมง</div>`);
  fn.bind=()=>{const m=$("#fbmsg");if(m){m.oninput=()=>{st.msg=m.value;const n=$("#fbn");if(n)n.textContent=m.value.length+"/1000"}}
    $$("[data-fbc]").forEach(b=>b.onclick=()=>{if(m)st.msg=m.value;st.cat=b.dataset.fbc;drawSheet()});
    {const mo=$("#fbmore");if(mo)mo.onclick=()=>{st.sent=false;st.msg="";drawSheet()}}
    {const sd=$("#fbsend");if(sd)sd.onclick=async()=>{st.msg=m.value.trim();st.err=null;
      if(st.msg.length<5){st.err=_T("เขียนอีกนิดนะครับ (อย่างน้อย 5 ตัวอักษร)");drawSheet();return}
      if(!location.protocol.startsWith("http")){st.err=_T("ส่งได้เฉพาะตอนเล่นบนเว็บ skyseatycoon.com");drawSheet();return}
      st.busy=true;drawSheet();
      try{const r=await fetch("/api/feedback",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({cat:st.cat,msg:st.msg,ver:GAME_VERSION+(IS_TEST?"-test":""),day:S?S.day:null,dev:devKind(),hp:($("#fbhp")||{}).value||""})});
        const j=await r.json().catch(()=>({ok:false,error:_T("เซิร์ฟเวอร์ตอบกลับผิดรูปแบบ")}));
        if(j.ok){st.sent=true;st.msg="";sfx("win")}else st.err=tr(j.error)||_T("ส่งไม่สำเร็จ")}catch(e){st.err=_T("ส่งไม่สำเร็จ ตรวจอินเทอร์เน็ตแล้วลองใหม่")}
      st.busy=false;drawSheet()}}};
  return fn}
/* ⚙️ Settings: everything the player can switch, in one place */
/* 🧪 Admin panel, test server only: shortcuts for checking new things quickly. Never reachable on the live site. */
function testDays(n){for(let i=0;i<n&&S&&!S.over;i++){settleFlights(S.day+1-1e-7);settleShips(S.day+1-1e-7);ferryTick(S.day+1-1e-7);simDay();pendingDec=null}acc=0;save();renderApp()}
function testSheet(){if(!IS_TEST)return ()=>"";
  const B=(id,t)=>`<button class="btn sm" data-tst="${id}">${t}</button>`;
  const fn=()=>head(_T("🧪 แผงทดสอบ"),_T("มีเฉพาะเว็บทดสอบ เว็บจริงไม่มี · เซฟของเว็บทดสอบแยกจากเว็บจริง"))+
   _T`<div class="setsec"><div class="eyebrow">💰 เงิน</div><div style="display:flex;flex-wrap:wrap;gap:6px">${B("m100",_T("+฿100 ล้าน"))}${B("m1b",_T("+฿1,000 ล้าน"))}${B("m0",_T("ตั้งเงินเป็น 0"))}${B("mneg",_T("ตั้งเงินติดลบ ฿50 ล้าน"))}</div>
    <div class="small muted">เงินตอนนี้ ${money(S.cash)}</div></div>
   <div class="setsec"><div class="eyebrow">⏩ ข้ามเวลา</div><div style="display:flex;flex-wrap:wrap;gap:6px">${B("d1",_T("+1 วัน"))}${B("d7",_T("+7 วัน"))}${B("d30",_T("+30 วัน"))}${B("d100",_T("+100 วัน"))}</div>
    <div class="small muted">คำนวณทุกวันตามจริง (รายได้ เหตุการณ์ คู่แข่ง) · เรื่องให้ตัดสินใจระหว่างข้ามจะถูกข้ามไป</div></div>
   <div class="setsec"><div class="eyebrow">🔓 ปลดล็อก</div><div style="display:flex;flex-wrap:wrap;gap:6px">${B("feat",_T("ปลดล็อกทุกระบบ"))}${B("reg",_T("ปลดล็อกทุกภูมิภาค"))}${B("lv",_T("เลเวล +1"))}${B("relock",_T("ล็อกระบบกลับเหมือนเกมใหม่"))}</div>
    <div class="small muted">ปลดล็อกแล้ว ${S.prog?S.prog.length:FEATS.length}/${FEATS.length} ระบบ · ภูมิภาค ${S.unlocked.length}/${REGIONS.length}</div></div>
   <div class="setsec"><div class="eyebrow">🛠️ อื่นๆ</div><div style="display:flex;flex-wrap:wrap;gap:6px">${B("fix",_T("ซ่อมทุกลำเป็น 100%"))}${B("dec",_T("เรียกเรื่องให้ตัดสินใจ"))}${B("rep",_T("ชื่อเสียง 100"))}</div></div>`;
  fn.bind=()=>{$$("[data-tst]").forEach(b=>b.onclick=()=>{const k=b.dataset.tst;
    if(k==="m100")S.cash+=1e8;else if(k==="m1b")S.cash+=1e9;else if(k==="m0")S.cash=0;else if(k==="mneg")S.cash=-5e7;
    else if(k[0]==="d"&&k!=="dec"){closeSheet();testDays(+k.slice(1));toast(_T`⏩ ข้ามไป ${k.slice(1)} วัน`);return}
    else if(k==="feat"){S.prog=FEATS.map(f=>f.id);applyFeat();refreshChrome()}
    else if(k==="relock"){S.prog=[];applyFeat();refreshChrome()}
    else if(k==="reg"){S.unlocked=REGIONS.map(R=>R.id);baseKey="";fogKey=""}
    else if(k==="lv")S.lvl=(S.lvl||1)+1;
    else if(k==="fix")S.fleet.forEach(p=>{p.cond=100;p.down=0});
    else if(k==="rep")S.rep=100;
    else if(k==="dec"){const d=pickDecision();if(d){closeSheet();openDecision(d);return}toast(_T("ตอนนี้ไม่มีเรื่องที่เข้าเงื่อนไข"));return}
    dispCash=S.cash;save();updateTop();toast(_T("🧪 ทำแล้ว"));drawSheet()})};
  return fn}
function settingsSheet(){
  const seg=(key,opts,val)=>`<div class="seg setseg">${opts.map(([v,n])=>`<button type="button" data-pset="${key}" data-v="${v}" class="${String(val)===String(v)?"on":""}">${n}</button>`).join("")}</div>`;
  const tg=(id,on,label,sub)=>`<label class="tg setrow"><input type="checkbox" data-ptg="${id}" ${on?"checked":""}><span><b>${label}</b>${sub?`<br><span class="small muted">${sub}</span>`:""}</span></label>`;
  const row=(label,sub,ctl)=>`<div class="setrow"><div><b>${label}</b>${sub?`<div class="small muted">${sub}</div>`:""}</div>${ctl}</div>`;
  const fn=()=>head(_T("⚙️ ตั้งค่า"),_T("ค่าการแสดงผล เสียง และการแจ้งเตือนเก็บไว้ในเครื่องนี้ · ค่าการเล่นเก็บไว้กับเซฟสายการบินนี้"))+
  _T`<div class="setsec"><div class="eyebrow">🖥️ การแสดงผล</div>
    ${row("🌐 ภาษา · Language","",seg("lang",[["th","ไทย"],["en","English"]],LANG))}
    ${row(_T("โหมดแสง"),"",seg("theme",THEMES.map(t=>[t[0],t[1]+" "+t[2]]),themePref()))}
    ${row(_T("ขนาดตัวอักษร"),_T("ขยายทั้งหน้าจอ"),seg("font",[["s",_T("เล็ก")],["m",_T("ปกติ")],["l",_T("ใหญ่")],["xl",_T("ใหญ่มาก")]],PREF.font))}
    ${row(_T("แอนิเมชัน"),_T("ลดการเคลื่อนไหวช่วยให้ลื่นขึ้นบนเครื่องรุ่นเก่า"),seg("motion",[["auto",_T("ตามเครื่อง")],["full",_T("เต็ม")],["less",_T("ลด")]],PREF.motion))}
    ${tg("fx",PREF.fx,_T("เอฟเฟกต์ฉลอง"),_T("พลุกระดาษ เหรียญกระจาย และเครื่องบินบินผ่านตอนได้รางวัล"))}
    ${tg("floats",PREF.floats,_T("ตัวเลขเงินลอยขึ้น"),_T("บนแผนที่ตอนเครื่องลงจอด และข้างยอดเงิน"))}
    ${S?tg("traf",S.ui_traf!==false,_T("ป้ายจำนวนคนบนแผนที่"),_T("ตัวเลขคนขึ้น-ลงที่แต่ละสนามบิน")):""}
    ${S?row(_T("รายการฝูงบิน"),"",seg("fview",[["",_T("อัตโนมัติ")],["row",_T("แถว")],["card",_T("การ์ด")]],S.ui_fview||"")):""}</div>
  <div class="setsec"><div class="eyebrow">🔔 การแจ้งเตือนและประกาศ</div>
    ${row(_T("ข้อความเด้งด้านล่าง"),_T("ประกาศจากเกม เช่น คู่ค้าขอความร่วมมือ รางวัล และผลจากปุ่มที่กด"),seg("toast",[["all",_T("ทั้งหมด")],["mine",_T("เฉพาะที่กด")],["off",_T("ปิด")]],PREF.toast))}
    ${S?tg("cel",!S.celOff,_T("ป๊อปอัปปลดล็อกและความสำเร็จ"),_T("การ์ดกลางจอตอนปลดล็อกระบบใหม่หรือได้ความสำเร็จ (ปิดแล้วยังดูได้ในข่าว)")):""}
    ${row(_T("รางวัลเข้าเกมรายวัน"),"",seg("daily",[["popup",_T("แสดงหน้าต่าง")],["silent",_T("รับให้อัตโนมัติ")]],PREF.daily))}
    ${row(_T("สรุปรายได้ตอนกลับมาเล่น"),_T("รายได้ระหว่างปิดเกมได้เท่าเดิมทั้งสองแบบ"),seg("away",[["popup",_T("แสดงหน้าต่าง")],["silent",_T("แค่ใส่ในข่าว")]],PREF.away))}
    <div class="setrow col"><div><b>ข่าวที่แสดงในหน้าหลัก</b><div class="small muted">ข่าวที่ปิดไว้ยังเกิดขึ้นตามปกติ แค่ไม่แสดงในรายการ</div></div>
     <div class="setchips">${NEWS_CATS.map(([k,n])=>`<label class="tg"><input type="checkbox" data-pnews="${k}" ${PREF.news[k]!==false?"checked":""}> ${n}</label>`).join("")}</div></div></div>
  <div class="setsec"><div class="eyebrow">🎮 การเล่น</div>
    ${row(_T("ความเร็วตอนเปิดเกม"),"",seg("speed0",SPEEDS.map(v=>[v,v+"×"]),PREF.speed0))}
    ${S?tg("amx",S.autoMx,_T("ส่งซ่อมบำรุงอัตโนมัติ"),_T("ส่งเครื่องที่สภาพต่ำกว่า 50% เข้าซ่อมเอง วันละไม่เกิน 1 ลำต่อเส้นทาง")):""}
    ${S?tg("aadv",!!S.autoAdv,_T("🤖 จัดการอัตโนมัติทุกวัน"),_T("ปรับราคา ย้ายเครื่องจากเส้นที่ว่างไปเส้นที่ล้น และใส่เครื่องจอดว่างให้เอง")):""}
    ${S?row(_T("ความเก่งของคู่แข่ง"),"",seg("diff",DIFFS.map(([k,n])=>[k,n]),S.diff||"auto")):""}</div>
  <div class="setsec"><div class="eyebrow">⚡ ความลื่นและกันเกมค้าง</div>
    ${row(_T("ความลื่นของแผนที่"),_T("อัตโนมัติ: วาดช้าลงเองเมื่อแผนที่มีเครื่องบินเยอะ · ประหยัดช่วยให้เครื่องไม่ร้อนและแบตอยู่นาน"),seg("mapfps",[["auto",_T("อัตโนมัติ")],["30",_T("ลื่น")],["15",_T("ประหยัด")],["8",_T("ประหยัดมาก")]],PREF.mapfps))}
    ${tg("lagGuard",PREF.lagGuard,_T("ลดความเร็วเองเมื่อเกมคำนวณไม่ทัน"),_T("ช่วงท้ายเกมที่มีเครื่องบินหลายร้อยลำ ความเร็ว 30× อาจทำให้จอค้าง เกมจะลดเป็น 10× หรือ 3× ให้เอง"))}
    <div class="small muted">เกมสำรองเซฟอัตโนมัติทุก 10 นาทีที่เล่น (เก็บ 3 ชุดล่าสุด) กู้คืนได้ที่ 💾 สำรอง / ย้ายเซฟ</div></div>
  <div class="setsec"><div class="eyebrow">🔊 เสียงและการสั่น</div>
    ${tg("sound",PREF.sound,_T("เสียงประกอบ"),_T("เสียงตอนซื้อ ได้รางวัล ได้เงิน และมีประกาศ"))}
    ${row(_T("ความดัง"),"",`<input type="range" id="pvol" min="0" max="1" step=".05" value="${PREF.vol}" style="max-width:180px">`)}
    ${S?tg("hap",S.haptic!==false,_T("สั่นเมื่อซื้อหรือได้รางวัล"),_T("ใช้ได้บนมือถือที่รองรับ")):""}</div>
  <div class="setsec"><div class="eyebrow">💾 ข้อมูลและเวอร์ชัน</div>
    <div class="row" style="gap:6px;flex-wrap:wrap">${has("afk")?_T`<button class="btn sm" id="pset-afk">💤 โหมด AFK</button>`:""}${IS_TEST?_T`<button class="btn sm" id="pset-test">🧪 แผงทดสอบ</button>`:""}<button class="btn sm" id="pset-save">💾 สำรอง / ย้ายเซฟ</button><button class="btn sm" id="pset-ver">ℹ️ v${GAME_VERSION} · มีอะไรใหม่</button><button class="btn sm" id="pset-help">❓ คู่มือระบบ</button><button class="btn sm" id="pset-fb">💬 ส่งความเห็นถึงผู้พัฒนา</button>${S?_T`<button class="btn sm danger" id="pset-reset">เริ่มเกมใหม่</button>`:""}<button class="btn sm" id="pset-def">คืนค่าเริ่มต้นการตั้งค่า</button></div></div>`;
  fn.bind=()=>{
    $$("[data-pset]").forEach(b=>b.onclick=()=>{const k=b.dataset.pset,v=b.dataset.v;
      if(k==="lang"){if(v!==LANG){try{localStorage.setItem("airline-lang",v)}catch(e){}if(S)save();location.reload()}return}
      if(k==="theme"){try{localStorage.setItem("airline-theme",v)}catch(e){}applyTheme(v);baseKey="";fogKey=""}
      else if(k==="fview"){if(S){S.ui_fview=v||undefined;save()}}
      else if(k==="diff"){if(S){S.diff=v;save()}}
      else{PREF[k]=k==="speed0"?+v:v;savePref();applyPrefs()}
      sfx("tap");drawSheet();if(S&&k!=="speed0")renderView()});
    $$("[data-ptg]").forEach(c=>c.onchange=()=>{const k=c.dataset.ptg,on=c.checked;
      if(k==="cel"){S.celOff=!on;save()}else if(k==="amx"){S.autoMx=on;save()}else if(k==="aadv"){S.autoAdv=on;if(on){S.autoMx=true;autoAdvTick()}save()}
      else if(k==="hap"){S.haptic=on;save();if(on)buzz(20)}else if(k==="traf"){S.ui_traf=on;save()}
      else{PREF[k]=on;savePref();applyPrefs();if(k==="sound"&&on)sfx("note")}
      drawSheet();if(S)renderView()});
    $$("[data-pnews]").forEach(c=>c.onchange=()=>{PREF.news={...PREF.news,[c.dataset.pnews]:c.checked};savePref();if(S)renderView()});
    {const v=$("#pvol");if(v){v.oninput=()=>{PREF.vol=+v.value;savePref()};v.onchange=()=>sfx("buy")}}
    $("#pset-save").onclick=()=>openSheet(saveSheet());
    {const b=$("#pset-afk");if(b)b.onclick=()=>{closeSheet();startAfk()}}{const b=$("#pset-test");if(b)b.onclick=()=>openSheet(testSheet())}
    $("#pset-ver").onclick=()=>openSheet(changelogSheet(null));
    $("#pset-help").onclick=()=>openSheet(guideSheet);
    $("#pset-fb").onclick=()=>openSheet(feedbackSheet());
    {const r=$("#pset-reset");if(r)r.onclick=()=>openSheet(resetSheet)}
    $("#pset-def").onclick=()=>{PREF={...PREF_DEF,news:{}};savePref();applyPrefs();toast(_T("คืนค่าการตั้งค่าในเครื่องนี้แล้ว"));drawSheet();if(S)renderView()}};
  return fn}
function resetSheet(){const L=S.last||{};return head(_T("เริ่มเกมใหม่?"),_T("ความคืบหน้าทั้งหมดของ ")+esc(S.name)+_T(" จะถูกลบ และย้อนกลับไม่ได้"))+_T`
  <div class="kv"><div><div class="k">เล่นมาแล้ว</div><div class="v">${S.day} วัน</div></div><div><div class="k">มูลค่ากิจการ</div><div class="v">${money(valuation(),true)}</div></div>
   <div><div class="k">เครื่องบิน / เรือ</div><div class="v">${S.fleet.length} / ${S.ships.length}</div></div><div><div class="k">ภารกิจสำเร็จ</div><div class="v">${S.mdone||0}</div></div></div>
  <label class="tg"><input type="checkbox" id="keepname" checked> ใช้ชื่อ ${esc(S.name)} และรหัส ${esc(S.code)} เหมือนเดิม</label>
  <div class="row"><button class="btn" style="flex:1" data-x>ยกเลิก</button><button class="btn danger" style="flex:1.3" id="yes">ลบและเริ่มใหม่</button></div>`}
resetSheet.bind=()=>{$("#yes").onclick=async()=>{if(S&&!S.over)await backupNow("reset");const keep=$("#keepname")&&$("#keepname").checked,nm=S.name,cd=S.code;
  S=null;save();sheetFn=null;pendingDec=null;selCity=null;view=null;baseCv=null;baseKey="";tab="home";document.body.classList.remove("onmap");
  rollFate();if(keep){fate.name=nm;fate.code=cd}window.scrollTo(0,0);renderApp()}};
function showOver(){const fn=()=>_T`<h2>${esc(S.name)} ล้มละลาย</h2><p class="muted" style="margin:0">เงินสดติดลบต่อเนื่อง 30 วัน ธนาคารเข้ายึดกิจการในวันที่ ${S.day+1}</p>
  <div class="kv"><div><div class="k">อยู่รอดได้</div><div class="v">${S.day} วัน</div></div><div><div class="k">ผู้โดยสารรวม</div><div class="v">${S.totPax.toLocaleString()}</div></div>
  <div><div class="k">ระดับสูงสุด</div><div class="v" style="font-family:var(--f-body)">${S.goal?GOALS[S.goal-1][1]:_T("สายการบินท้องถิ่น")}</div></div><div><div class="k">ความสำเร็จ</div><div class="v">${S.ach.length}/${ACH.length}</div></div></div>
  <button class="btn primary block" id="yes">เริ่มสายการบินใหม่</button>`;fn.bind=resetSheet.bind;openSheet(fn)}

function guideSheet(){return head(_T("คู่มือระบบ"),_T("ทุกระบบในเกมทำงานอย่างไร"))+_T`<div>
<details class="g" open><summary>เป้าหมายของเกม</summary><div><p>ทำให้มูลค่ากิจการโตจนขึ้นถึงระดับ "ตำนานแห่งท้องฟ้า" และแซงคู่แข่งอีก 5 สายการบินในตารางอันดับ · อันดับแต่ละด้านมีผลกับความร่วมมือ: ด้านไหนเราอันดับสูง พันธมิตรด้านนั้นตกลงง่าย คิดราคาถูก และดีลได้ผลแรงกว่า · นอกจากอันดับรวมยังมีการแข่งแยกหมวด: มูลค่า ผู้โดยสาร สินค้าทางอากาศ เดินเรือ และบริการ คู่แข่งแต่ละเจ้าเก่งคนละด้าน (เช่น เมฆาเวย์เด่นเดินเรือ โกลเด้นวิงเด่นสินค้า อันดามันแอร์เด่นบริการ) · คู่แข่งแต่ละเจ้ามีแผนของตัวเอง (ขยายเชิงรุก / โตต่อเนื่อง / ระมัดระวัง) และเปลี่ยนแผนได้ทุกไม่กี่สัปดาห์ เจ้าที่ตามหลังเป้าจะเร่งขยาย เจ้าที่นำเกินเป้าจะชะลอ</p><p>มูลค่ากิจการ = เงินสด + มูลค่าขายต่อของฝูงบิน − เงินกู้</p><ul>${GOALS.map(g=>`<li>${g[1]}: ${money(g[0])}</li>`).join("")}</ul></div></details>
<details class="g"><summary>เวลาและความเร็ว</summary><div><p>ที่ความเร็ว 1× เวลาในเกม 1 ชั่วโมงเท่ากับ 1.25 วินาทีจริง (1 วัน = 30 วินาที) เครื่องบินบนแผนที่ใช้เวลาบินตามระยะทางและความเร็วจริงของรุ่น กด 3×, 10× หรือ 30× เพื่อเร่ง กด ❚❚ เพื่อหยุดคิด ระบบคิดรายรับรายจ่ายทุกสิ้นวัน และเซฟอัตโนมัติในเบราว์เซอร์นี้</p></div></details>
<details class="g"><summary>คนอยากบินกี่คน</summary><div><p>แต่ละเส้นทางมีความต้องการผู้โดยสารต่อวัน คำนวณจาก</p><ul><li><b>ขนาดเมือง</b> ทั้งต้นทางและปลายทาง เมืองใหญ่อย่างโตเกียวหรือนิวยอร์กมีคนบินเยอะ</li><li><b>ระยะทาง</b> สั้นกว่า 300 กม. คนนิยมนั่งรถมากกว่า ไกลมากคนก็บินน้อยลง</li><li><b>ราคาตั๋ว</b> ถูกกว่าราคากลางคนเพิ่มขึ้นแรง แพงกว่าคนหายเร็ว</li><li><b>ชื่อเสียง</b> 0–100 ชื่อเสียง 50 คือปกติ</li><li><b>ระดับบริการ</b> การตลาด และเหตุการณ์ เช่น เทศกาลหรือคู่แข่ง</li></ul><p>ผู้โดยสารจริง = น้อยกว่าระหว่างคนอยากบินกับที่นั่งที่มี และแต่ละเที่ยวแกว่งขึ้นลงราว ±12%</p></div></details>
<details class="g"><summary>เที่ยวบินต่อวันและที่นั่ง</summary><div><p>เครื่องบินจริงไม่ได้บิน 24 ชม. ต้องพักกลางคืน ซ่อมบำรุง และใช้เวลาบนพื้นระหว่างเที่ยว (ทำความสะอาด เติมน้ำมัน ขึ้นลงผู้โดยสาร) เกมจึงคิดตามประเภทเครื่อง:</p>
<ul><li>ใบพัด: บินได้ ~15 ชม./วัน · พักระหว่างเที่ยว ~25 นาที</li><li>ลำตัวแคบ (A320, 737): ~17.5 ชม./วัน · พัก ~45 นาที</li><li>ลำตัวกว้างและเครื่องขนสินค้าใหญ่: ~20 ชม./วัน · พัก ~1.8 ชม.</li></ul>
<p><code>เที่ยว/วัน = ชม.ทำงาน ÷ (ระยะทาง ÷ ความเร็ว + 0.5 + เวลาพัก)</code> สูงสุดวันละ 12 เที่ยว · เส้นทางไกลมาก (เช่น กรุงเทพ–ลอนดอน) บินได้วันละเที่ยวเดียว เหมือนจริง</p><p>ตารางบินแบบ "ปรับตามผู้โดยสาร" (ค่าเริ่มต้น) จะลดเที่ยวบินลงเมื่อคนน้อย ให้แต่ละเที่ยวเต็มราว 85% ส่วน "บินเต็มตาราง" บินทุกเที่ยวเสมอ เหมาะตอนมีเทศกาลหรือแคมเปญ</p><p>เส้นทางสั้นใช้เครื่องลำเล็กคุ้มเพราะบินได้หลายรอบ เส้นทางไกลต้องใช้เครื่องที่พิสัยถึงและจุคนเยอะ ใส่เครื่องหลายลำในเส้นทางเดียวได้</p></div></details>
<details class="g"><summary>ราคาตั๋ว</summary><div><p>หน้าเส้นทางมีกล่องคาดการณ์บอกกำไรหรือขาดทุนต่อวันแบบดูง่าย ปรับราคาด้วยแถบเลื่อนหรือปุ่มลัด (−10%, ราคากลาง, +10%, กำไรสูงสุด) และเลือกบริการแยกเฉพาะเส้นทางได้ ใต้ปุ่มบริการบอกกำไรที่คาดว่าจะได้</p><p>เส้นทางใหม่ใช้ "ราคาอัตโนมัติตามคน" ระบบขึ้นราคาเมื่อคนอยากบินมากกว่าที่นั่ง (เช่น ช่วงเทศกาลหรือแคมเปญ) และลดราคาเมื่อคนน้อย ให้เครื่องเต็มราว 90% ตารางราคาในหน้าเส้นทางบอกว่าราคาแต่ละระดับมีคนบินกี่คน ที่นั่งเต็มกี่ % และกำไรเท่าไร แถว ★ คือราคาที่กำไรสูงสุด แตะแถวเพื่อลองราคา · ปุ่ม 🏷️ ปรับราคาทุกเส้น ในแท็บเส้นทางหรือหน้าหลักเปลี่ยนราคาหลายเส้นพร้อมกันได้</p><p>ราคากลางคำนวณจากระยะทาง ตั้งได้ตั้งแต่ครึ่งหนึ่งถึงสองเท่าของราคากลาง ถ้าที่นั่งเต็มเกือบ 100% แปลว่าขึ้นราคาได้อีก ถ้าเต็มแค่ครึ่งเดียว ลองลดราคาหรือเปลี่ยนเป็นเครื่องลำเล็กลง หน้าต่างเส้นทางจะคำนวณกำไรให้ดูทันทีที่เลื่อนราคา</p></div></details>
<details class="g"><summary>ขนส่งทางเรือ</summary><div><p>สลับเป็นโหมดสินค้า แล้วไปที่แท็บเส้นทาง → ทางเรือ เพื่อเปิดเส้นทางเรือระหว่างท่าเรือ ${PORTS.length} แห่งทั่วโลก (ต้องปลดล็อกภูมิภาคก่อน) แล้วซื้อเรือใส่ เรือวิ่งตามเส้นทางทะเลจริง ผ่านช่องแคบมะละกา คลองสุเอซ คลองปานามา หรืออ้อมแหลม</p><p>เรือแล่นราว ${Math.min(...SHIPS.map(m=>m.speed))}–${Math.max(...SHIPS.map(m=>m.speed))} กม./ชม. เที่ยวยุโรป–เอเชียใช้ราว 2–3 สัปดาห์ในเกม แล้วจอดขนตู้ที่ท่า 1–2 วัน ได้เงินเมื่อเรือถึงท่า ค่าระวางต่อตู้ = ฿${Math.round(TEU_RATE(0)).toLocaleString()} + ฿${(TEU_RATE(1000)/1000-TEU_RATE(0)/1000).toFixed(1)} ต่อกม. เรือห้องเย็นได้ 1.8 เท่าแต่ตลาดเล็กกว่า เรือ ULCV ต้องใช้ท่าเรือน้ำลึกทั้งสองฝั่ง</p><p>เหตุการณ์: คลองสุเอซปิด (เรืออ้อมแหลมกู๊ดโฮป) และท่าเรือนัดหยุดงาน</p></div></details>
<details class="g"><summary>ขนส่งสินค้า</summary><div><p><b>ระยะทางกับความต้องการ:</b> สินค้าทางอากาศและทางเรือแทบไม่ลดลงตามระยะทาง เส้นทางไกลจึงคุ้มกับเครื่องบินขนสินค้าและเรือลำใหญ่ ส่วนผู้โดยสารจะค่อย ๆ น้อยลงเมื่อไกลมาก และเมืองเล็กมีความต้องการน้อยกว่าเมืองใหญ่เสมอ</p><p>เส้นทางแบ่งเป็น 2 แบบ ใช้สาขาเดียวกัน: <b>เส้นทางผู้โดยสาร</b> ใส่ได้เฉพาะเครื่องบินโดยสาร (ขนพัสดุใต้ท้องเครื่องได้ราวครึ่งหนึ่งของตลาด) และ <b>เส้นทางขนสินค้า</b> ใส่ได้เฉพาะเครื่องบินขนสินค้า เลขเที่ยวบินขึ้นต้น 8xx เส้นบนแผนที่เป็นสีม่วง เปิดทั้งสองแบบไปเมืองเดียวกันได้</p><p>มีเครื่องขนสินค้า ${MODELS.filter(m=>!m.seats).length} รุ่น ตั้งแต่ ${(()=>{const L=MODELS.filter(m=>!m.seats).sort((a,b)=>a.cargo-b.cargo);return _T`${L[0].name} (${L[0].cargo} ตัน) ถึง ${L[L.length-1].name} (${L[L.length-1].cargo} ตัน)`})()} แต่ละเส้นทางตั้งค่าระวางได้เองหรือให้ระบบตั้งอัตโนมัติ ช่วงฤดูผลไม้ไทย ช้อปปิ้ง 11.11 และปลายปี สินค้าจะเยอะขึ้น ดูปฏิทินได้ในแท็บเส้นทาง (โหมดสินค้า)</p><p>ทุกเที่ยวบินขนสินค้าใต้ท้องเครื่องได้ ส่วน Boeing 777F ขนสินค้าอย่างเดียว 100 ตันต่อเที่ยว รายได้สินค้าคิดค่าจัดการต่อตันบวกตามระยะทาง (ราว ฿${Math.round(cgRate(1500)/1000)}/กก. ที่ 1,500 กม. และ ฿${Math.round(cgRate(9000)/1000)}/กก. ที่ 9,000 กม.) ความต้องการสินค้าขึ้นกับขนาดเมืองและระยะทาง สินค้าไม่สนราคาตั๋วหรือชื่อเสียง</p></div></details>
<details class="g"><summary>เงินเข้าออกตอนไหน</summary><div><p>ทุกครั้งที่เครื่องบินลงจอด คุณได้ค่าตั๋วและค่าขนสินค้าของเที่ยวนั้นทันที และจ่ายค่าน้ำมัน ค่าสนามบิน และค่าบริการบนเครื่องของเที่ยวนั้นไปพร้อมกัน ตัวเลขเขียวหรือแดงจะลอยขึ้นจากสนามบินที่ลงจอดบนแผนที่</p><p>ตอนเที่ยงคืนระบบหักค่าใช้จ่ายคงที่ ได้แก่ ค่าดูแลเครื่องบิน ค่าลูกเรือ และดอกเบี้ย แล้วสรุปเป็นงบเมื่อวานในแท็บการเงิน</p></div></details>
<details class="g"><summary>ต้นทุน</summary><div><ul><li><b>ค่าน้ำมัน</b> = จำนวนเที่ยว × ระยะทาง × ค่าบินต่อกม.ของรุ่น × ดัชนีน้ำมัน</li><li><b>ค่าสนามบิน</b> แต่ละเมืองเก็บไม่เท่ากัน ลอนดอนและนิวยอร์กแพงสุด คิดตามขนาดเครื่อง</li><li><b>ค่าดูแลเครื่องและลูกเรือ</b> ${(FIX_RATE*100).toFixed(2)}% ของราคาเครื่องต่อวัน ถ้าจอดว่างเหลือ 0.06% · ทุกเส้นทางเสียค่าเช่าช่องจอด ${money(ROUTE_SLOT)}/วัน แม้ยังไม่มีเครื่อง</li><li><b>ค่าบริการ</b> ต่อผู้โดยสาร ตามระดับบริการ</li><li><b>ดอกเบี้ย</b> เงินกู้ 6–36% ต่อปี ยิ่งหนี้มากเทียบกับทรัพย์สิน ดอกเบี้ยยิ่งสูง</li></ul></div></details>
<details class="g"><summary>สภาพเครื่องและการซ่อมบำรุง</summary><div><p>ทุกเที่ยวที่บิน สภาพเครื่องลดลง 0.035% เครื่องที่สภาพต่ำมีโอกาสขัดข้องกลางทาง ต้องจอด 3 วัน เสียเงินและชื่อเสียง ถ้าสภาพเฉลี่ยของฝูงบินต่ำกว่า 60% ชื่อเสียงจะค่อย ๆ ลด</p><p>ส่งซ่อมบำรุงได้เองหรือเปิดโหมดอัตโนมัติ ใช้เวลา 2 วันแล้วสภาพกลับเป็น 100% ราคาขายต่อลดลงตามอายุและสภาพเครื่อง</p></div></details>
<details class="g"><summary>ชื่อเสียงและระดับบริการ</summary><div><p>ชื่อเสียงจะค่อย ๆ เคลื่อนเข้าหาค่าเป้าหมายของระดับบริการ ประหยัด 35 มาตรฐาน 60 พรีเมียม 85 คลิปไวรัลและแคมเปญใหญ่ช่วยดันขึ้น เครื่องเสียกลางทางทำให้ลดลง</p></div></details>
<details class="g"><summary>การตลาดและล็อกราคาน้ำมัน</summary><div><p>แคมเปญการตลาดเพิ่มคนบินทุกเส้นทางชั่วคราว เปิดได้ทีละแคมเปญ</p><p>ดัชนีน้ำมันขึ้นลงทุกวันและพุ่งแรงได้จากเหตุการณ์ การล็อกราคาจะตรึงดัชนีไว้ 60 วัน ค่าธรรมเนียมประมาณ 3% ของค่าน้ำมันช่วงนั้น เหมาะตอนน้ำมันถูก</p></div></details>
<details class="g"><summary>เงินกู้และการล้มละลาย</summary><div><p>กู้ได้ทีละ ฿50 ล้าน วงเงินขึ้นกับมูลค่าฝูงบิน ถ้าเงินสดติดลบต่อเนื่อง 30 วัน สายการบินล้มละลายและต้องเริ่มสายการบินใหม่ (หรือกู้คืนจากเซฟสำรองอัตโนมัติก่อนล้มละลาย)</p></div></details>
<details class="g"><summary>✈ รอสินค้าก่อนออกบิน (เครื่องบินขนสินค้า)</summary><div><ul><li>ตั้งในหน้าเส้นทางขนสินค้า: บินตามตาราง หรือรอจนระวางเต็ม 50 / 75 / 95% ก่อนบิน</li><li>บินน้อยลงแต่เต็มขึ้น ประหยัดน้ำมันและค่าสนามบิน แต่ส่งช้าลง ลูกค้าจ่ายน้อยลงสูงสุด ${Math.round(LATE*100)}% และอาหารเสียความสดอีกสูงสุด ${Math.round(AIR_SPOIL*100)}%</li><li>ใช้ร่วมกับ “ตารางบิน” ได้: ถ้าตั้งบินเต็มตาราง การรอจะช่วยมาก ถ้าตั้งปรับตามสินค้า (เต็มราว 85% อยู่แล้ว) การรอจะช่วยน้อย</li></ul></div></details>
<details class="g"><summary>🚢 เรือเฉพาะ และ ⏳ รอสินค้าก่อนออกเรือ</summary><div><ul><li>เรือห้องเย็นและเรือขนรถขนได้อย่างเดียวแต่เต็มลำ ได้ค่าระวางมากกว่า ${Math.round((SPEC_RATE-1)*100)}% และอาหารไม่เสียความสดตอนรอ</li><li>เรือรวมขนได้ทุกอย่างทีละประเภท แต่ใช้พื้นที่ขนอาหารได้แค่ ${Math.round(SEA_LOAD.r*100)}% และขนรถได้แค่ ${Math.round(SEA_LOAD.o*100)}% ของความจุ</li><li>⏳ รอสินค้า: ตั้งในหน้าเส้นทางเรือ ให้เรือรอที่ท่าจนตู้เต็ม 50 / 75 / 95% ก่อนออก ออกเรือน้อยลงจึงประหยัดน้ำมันและค่าท่า แต่ส่งช้าลง ลูกค้าจ่ายน้อยลงสูงสุด ${Math.round(LATE*100)}% และอาหารบนเรือรวมเสียความสดเพิ่มอีก</li><li>ตัวเลขใต้ปุ่มบอกกำไร/วันของแต่ละแบบ ⭐ คือแบบที่ดีที่สุดตอนนั้น เหมาะกับเส้นทางที่เรือใหญ่เกินสินค้า</li></ul></div></details>
<details class="g"><summary>🤝 ความร่วมมือ และ 🌐 จดหมายเหตุโลก</summary><div><ul><li>แท็บบริษัท → ความร่วมมือ: กด “ขอความร่วมมือ” เลือกพันธมิตร (สายการบินคู่แข่ง บริษัทน้ำมัน บริษัทขนส่ง ผู้ผลิตเครื่องบิน การท่องเที่ยวเมืองต่าง ๆ สนามบินสาขา) แล้วเลือกข้อเสนอ เกมบอกราคา ผล และโอกาสที่เขาจะตกลง</li><li>ข้อเสนอ (ผลจริงแรงขึ้นหรืออ่อนลง ×0.8–1.2 ตามอันดับของเราในด้านที่พันธมิตรสนใจ): โค้ดแชร์ (คน +8%) · สงบศึกราคา (คู่แข่งถอนตัว) · โปรโมทท่องเที่ยว (เมืองนั้น +35%) · สัญญาน้ำมัน (−10%) · สัญญาขนส่งสินค้า (+25%) · ส่วนลดเครื่องบิน (−12%) · พันธมิตรสนามบิน (ค่าธรรมเนียม −25%)</li><li>อีกฝ่ายก็ขอความร่วมมือเราได้ (📨 คำขอที่เข้ามา) ตอบได้ 3 แบบ: ตกลง · ต่อรองกลับ (ขอถูกลง 20% และนานขึ้น 50% ถ้าเขาไม่ยอมคำขอจะยกเลิก) · ปฏิเสธ</li><li>แต่ละพันธมิตรมีความสัมพันธ์ 0–100 ตกลงกันได้ความสัมพันธ์เพิ่ม ถูกปฏิเสธหรือแย่งเส้นทางกันความสัมพันธ์ลด ความสัมพันธ์ เรตติ้ง และชื่อเสียงสูง เขาจะตกลงง่ายขึ้น</li><li>🌐 แผนที่ → ปุ่มสถานการณ์โลก: สรุปสั้น ๆ ว่าโลกตอนนี้เป็นอย่างไร น้ำมัน เทศกาล พายุ ฤดูสินค้า คลองสุเอซ คู่แข่ง และดีลของเรา</li></ul></div></details>
<details class="g"><summary>🛟 เครื่องบินและเรือสำรอง</summary><div><p>ตั้งเครื่องบินหรือเรือเป็นตัวสำรองได้จากหน้าของลำนั้น ตัวสำรองจะจอดที่ฐานสำรอง (มีทวีปละ 1 แห่งสำหรับเครื่องบิน และ 1 แห่งสำหรับเรือ) ซึ่งเป็นที่จอดอย่างเดียว ไม่มีเส้นทางของตัวเอง</p><p>เมื่อเส้นไหนคนหรือสินค้าล้น ระบบจะส่งตัวสำรองจากฐานที่ใกล้ที่สุดไปช่วย ไปได้ทุกที่ในโลก แต่เส้นที่ช่วยต้องอยู่ในพิสัยของลำนั้น บนแผนที่จะเห็นตัวเครื่องหรือเรือเดินทางไป ค่าน้ำมันเที่ยวไปและกลับคิดตามระยะ พอเส้นนั้นมีที่ว่างพอ 3 วันติด ตัวสำรองจะกลับฐานเอง และเส้นนั้นจะเรียกตัวสำรองใหม่ได้อีกใน 7 วัน ดูภาพรวมของทุกฐานได้ที่แท็บสาขา</p></div></details>
<details class="g"><summary>⚙️ ตั้งค่า เซฟสำรอง และกันเกมค้าง</summary><div><p>เมนู ··· → ⚙️ ตั้งค่า มี 6 หมวด: การแสดงผล (โหมดแสง ขนาดตัวอักษร แอนิเมชัน) · การแจ้งเตือนและประกาศ (ข้อความเด้ง ป๊อปอัป ประเภทข่าว) · การเล่น · ความลื่นและกันเกมค้าง · เสียงและการสั่น · ข้อมูลและเวอร์ชัน</p><p>เซฟเก็บในเบราว์เซอร์ของเครื่องนี้ เกมสำรองเซฟอัตโนมัติทุก 10 นาทีที่เล่น และก่อนนำเข้าเซฟหรือเริ่มเกมใหม่ (เก็บ 3 ชุดล่าสุด) ถ้าจะย้ายไปเล่นเครื่องอื่น ใช้ 💾 สำรอง / ย้ายเซฟ เพื่อดาวน์โหลดไฟล์หรือคัดลอกรหัสเซฟ</p><p>ถ้าเกมใหญ่จนคำนวณไม่ทันที่ความเร็วสูง เกมจะลดความเร็วให้เอง และถ้าเจอข้อผิดพลาดซ้ำ ๆ เกมจะหยุดเวลาแล้วให้เลือกเล่นต่อ ลดความเร็ว หรือกู้คืนเซฟ แทนที่จะค้าง</p></div></details>
<details class="g"><summary>📋 แต่ละแท็บมีอะไร</summary><div><ul><li><b>ภาพรวม</b> สิ่งที่เกิดขึ้นตอนนี้: แผนที่ เงินวันนี้ เที่ยวบินสด ภารกิจ ข่าว</li><li><b>แผนที่</b> แผนที่เต็มจอ</li><li><b>เส้นทาง</b> เส้นทางบินและเส้นทางเรือ</li><li><b>สาขา</b> สนามบินและท่าเรือของเรา</li><li><b>ฝูงบิน</b> เครื่องบินและเรือที่เรามี ปุ่มซื้อเพิ่ม</li><li><b>การเงิน</b> รายได้ ต้นทุน เงินกู้</li><li><b>บริษัท</b> ตัวตนของสายการบิน: เรตติ้ง ความคิดเห็นลูกค้า การแข่งขัน เป้าหมาย ศูนย์พัฒนา สถิติ ความสำเร็จ</li></ul></div></details>
<details class="g"><summary>🏆 อันดับและความยากของคู่แข่ง</summary><div><ul><li>มีระบบเดียว: ตารางอันดับ คะแนนมาจากขนาดบริษัท (มูลค่ากิจการ ผู้โดยสาร สินค้า ตู้เรือ เรตติ้ง ภารกิจ) สะสมตลอดเกม ขยายกิจการแล้วคะแนนขึ้นเสมอ</li><li>ความยากของคู่แข่งเลือกได้ (ง่าย / ปกติ / ยาก / ตามฝีมือ) ตอนเริ่มเกมหรือในแท็บบริษัท แบบ “ตามฝีมือ”: ยิ่งนำอันดับ 2 ห่าง คู่แข่งยิ่งเก่งขึ้น (โตเร็วขึ้น บุกเส้นทางบ่อยขึ้น ตัดราคาแรงขึ้น ถอนตัวยากขึ้น) ถ้าเราตามหลัง คู่แข่งจะผ่อนลง ค่อย ๆ ปรับวันละนิด ไม่กระโดด</li><li>ดูได้ในแท็บบริษัท และปุ่ม 🏆 บนแผนที่</li></ul></div></details>
<details class="g"><summary>✨ ฟีเจอร์ที่ค่อย ๆ ปลดล็อก</summary><div><p>เกมใหม่จะเริ่มแค่ ภาพรวม เส้นทาง และฝูงบิน ระบบอื่นจะเปิดทีละอย่าง (ไม่เกินวันละอย่าง) พร้อมกล่องแจ้งเตือน ✨ แยกจากภารกิจ:</p><ol>${FEATS.filter(f=>has(f.id)).map(f=>`<li><b>${f.n}</b></li>`).join("")}</ol>${FEATS.some(f=>!has(f.id))?_T`<p>🔒 ยังมีอีก ${FEATS.filter(f=>!has(f.id)).length} อย่าง · อย่างต่อไปจะเปิดเมื่อ: ${FEATS.filter(f=>!has(f.id)&&(f.after||[]).every(has)).map(f=>`<b>${f.need}</b>`).join(_T(" หรือ "))}</p>`:""}<p class="small">ทุกการขยายกิจการต้องมีฐานที่มั่นคงก่อน คือกำไรเฉลี่ย 7 วันเป็นบวก สินค้าทางอากาศเริ่มจากพัสดุกับเครื่องลำเล็ก แล้วค่อยเปิดอาหาร เครื่องลำใหญ่ ชิ้นส่วน/รถ ส่วนเรือเริ่มจากเรือเล็กขนตู้พัสดุ แล้วค่อยเปิดเรือห้องเย็น เรือใหญ่ และเรือขนรถ</p><p class="muted small">เซฟเก่าก่อนมีระบบนี้เปิดครบทุกอย่างอยู่แล้ว</p></div></details>
<details class="g"><summary>🧭 พิสัยบิน/แล่น 🔗 ต่อเครื่อง และถ่ายลำ</summary><div><ul><li>เครื่องบินทุกรุ่นมีระยะบินไกลสุด เครื่องโดยสารไกลสุด ${AIR_MAX_P.toLocaleString()} กม. เครื่องขนสินค้า ${AIR_MAX_C.toLocaleString()} กม. ปลายทางที่ไกลกว่านั้นเปิดเส้นทางบินตรงไม่ได้</li><li>เรือก็มีระยะแล่นไกลสุด เรือชายฝั่งและฟีดเดอร์วิ่งได้แค่ในภูมิภาค เส้นทางข้ามทวีปต้องใช้เรือใหญ่ ดูได้ที่ “แล่นได้ไกล” ในอู่ต่อเรือ</li><li>🔗 ต่อเครื่อง: ผู้โดยสาร (และสินค้า) ระหว่างสองเมืองที่เราไม่มีเที่ยวบินตรง จะต่อเครื่องที่<b>สาขา</b>ของเราได้สูงสุด 2 ครั้ง (3 เที่ยวบิน) ถ้าทางอ้อมไม่ไกลเกินไป เช่น กรุงเทพ → ดูไบ → เซาเปาโล</li><li>คนต่อเครื่องจะเพิ่มเข้าไปในทุกเส้นทางที่ใช้ จ่ายค่าตั๋วตามราคาของแต่ละช่วง ดูได้ที่กล่อง 🔗 ในหน้าเส้นทาง</li><li>🚢 ถ่ายลำ: เรือก็เหมือนกัน ตู้สินค้าระหว่างท่าที่ไม่มีเรือวิ่งตรง จะขนต่อกันที่<b>สาขาท่าเรือ</b>ได้สูงสุด 2 ครั้ง ดูได้ที่กล่อง 🔗 ในส่วนเส้นทางเรือ</li><li>อยากไปที่ไกลเกินบินตรง: เปิดสาขาที่เมืองกลางทาง แล้วเปิดเส้นทางทั้งสองช่วง หน้าเปิดเส้นทางจะแนะนำเมืองให้</li></ul></div></details>
<details class="g"><summary>📥 ระบบสะสม (คนและสินค้าที่รอ)</summary><div><ul><li>ทันทีที่<b>เปิดเส้นทาง</b> ระบบสะสมของเส้นนั้นจะเริ่มทำงาน แม้ยังไม่มีเครื่องบินหรือเรือวิ่งเลยก็ตาม</li><li>ทุกสิ้นวัน คนหรือสินค้าที่ไม่มีใครขนไป ส่วนหนึ่งจะรอไว้: ผู้โดยสาร 35% (สะสมได้สูงสุดเท่ากับความต้องการ 3 วัน) · สินค้าทางอากาศ 60% (สูงสุด 6 วัน) · ตู้สินค้าทางเรือ 60% (สูงสุด 8 วัน)</li><li>เมื่อมีเครื่องบินหรือเรือที่มีที่ว่าง ของที่สะสมจะถูกขนไปเองและได้เงินเพิ่ม โดยจ่ายไม่เกินราคากลาง ตารางบินแบบปรับตามคนจะเพิ่มเที่ยวให้เองระหว่างที่ยังมีของสะสม</li><li>ดูยอดสะสมได้จากป้าย 📥 บนการ์ดเส้นทาง และในหน้ารายละเอียดเส้นทาง</li><li><b>ปิดเส้นทางเมื่อไร ของที่สะสมไว้จะหายไปทั้งหมด</b></li></ul></div></details>
<details class="g"><summary>✨ โบนัส: ฉลองยอดสะสม รางวัลรายวัน และเลเวล</summary><div><ul><li>🎉 เมื่อผู้โดยสารสะสม (หรือสินค้าทางอากาศสะสม) ถึงหลักสำคัญ เช่น 1,000 · 5,000 · 20,000 ไปจนถึงหลักล้าน จะได้โบนัสฉลองทันที ดูความคืบหน้าได้ในการ์ดบนสุดของหน้าหลัก</li><li>🔬 ศูนย์พัฒนาในแท็บบริษัท: จ่ายเงินอัปเกรดถาวร 4 อย่าง (ประหยัดน้ำมัน · คนอยากบินเพิ่ม · รายได้สินค้าเพิ่ม · ค่าธรรมเนียมถูกลง) อย่างละ 5 ระดับ</li><li>🛫 เที่ยวบินสดในหน้าหลัก เห็นเครื่องบินวิ่งไปกลับบนแต่ละเส้นทาง พร้อมเงินที่เส้นทางนั้นทำได้วันนี้ แตะแถวเพื่อเปิดเส้นทางนั้น</li><li>🎁 เข้าเกมทุกวัน (วันจริง) รับรางวัลรายวัน ต่อเนื่องครบ 7 วันได้ก้อนใหญ่</li><li>Lv ข้างชื่อสายการบินคือเลเวล คิดจากคะแนนการแข่งขัน ขึ้นเลเวลแต่ละครั้งได้โบนัส แถบเล็กใต้ Lv บอกว่าใกล้เลเวลถัดไปแค่ไหน</li></ul></div></details>
<details class="g"><summary>🧭 ช่วยเลือกเครื่องบินและเรือ</summary><div><p>ไม่รู้จะซื้อรุ่นไหน ให้กดปุ่ม 🧭 ในแท็บฝูงบิน (เรืออยู่ในโหมดสินค้า) หรือกด "ดูทุกรุ่น" ในกล่องเพิ่มเครื่องบิน/เรือบนแผนที่ เลือกเส้นทาง แล้วเกมจะเรียงทุกรุ่นตามกำไรต่อวันที่จะเพิ่มขึ้น</p><ul><li>⭐ คุ้มที่สุด: ทำกำไรเพิ่มได้มากที่สุด</li><li>⚡ คืนทุนเร็วสุด: ราคาซื้อคืนกลับมาเร็วที่สุด</li><li>รุ่นที่บินไม่ถึง หรือเทียบท่าไม่ได้ จะแยกไว้ด้านล่างพร้อมบอกเหตุผล</li></ul><p>ชนิดเรือ: 📦 ตู้คอนเทนเนอร์ ขนสินค้าทั่วไป · ❄ ห้องเย็น ขนผลไม้และอาหาร ค่าระวาง 1.8 เท่า · 🚗 ขนรถ ค่าระวาง 1.5 เท่า แต่ละชนิดมีสินค้าของตัวเอง เรือต่างชนิดเลยไม่แย่งสินค้ากันบนเส้นทางเดียวกัน</p><p>บนแผนที่ กดปุ่มลูกศรที่มุมแถบด้านบนเพื่อย่อแถบให้เหลือแค่ชื่อกับเงิน</p></div></details>
<details class="g"><summary>โหมดคน และ โหมดสินค้า</summary><div><p>ปุ่มใต้แถบด้านบนสลับทั้งเกมระหว่าง 2 โหมด</p><ul><li>👥 โหมดคน: แผนที่ เส้นทาง ฝูงบิน และกล่องข้อมูลสนามบิน แสดงเฉพาะเครื่องบินโดยสารและเส้นทางผู้โดยสาร ป้ายบนแผนที่บอกจำนวนคนขึ้นเครื่อง</li><li>📦 โหมดสินค้า: แสดงเฉพาะเครื่องบินขนสินค้า เส้นทางสินค้า และเรือ ป้ายบนแผนที่บอกสินค้าเป็นตัน กดสนามบินแล้ว + เพิ่มเครื่องบิน จะขึ้นเฉพาะเครื่องขนสินค้า</li></ul><p>เงิน สาขา และเวลาใช้ร่วมกันทั้ง 2 โหมด เครื่องบินทุกลำยังบินและทำเงินตลอด ไม่ว่าจะเปิดโหมดไหน</p></div></details>
<details class="g"><summary>ประเภทสนามบิน</summary><div><ul><li>✈📦 สนามบินส่วนใหญ่รับทั้งผู้โดยสารและสินค้า</li><li>✈ สนามบินเล็กเมืองท่องเที่ยว เช่น สมุย ฟูก๊วก ควีนส์ทาวน์ รับเฉพาะผู้โดยสาร</li><li>📦 ฮับสินค้า เช่น เมมฟิส หลุยส์วิลล์ ลีแยฌ ไลพ์ซิก เออโจว ดูไบเวิลด์เซ็นทรัล รับเฉพาะสินค้า (จุดสี่เหลี่ยมสีม่วงบนแผนที่)</li></ul><p>ป้าย 👥 บนแผนที่ข้างสนามบินของคุณคือจำนวนคนที่ขึ้นเครื่องที่นั่นวันนี้ แตะสนามบินเพื่อดูคนขึ้น คนลง และสินค้าเข้าออก เทียบกับเมื่อวาน</p></div></details>
<details class="g"><summary>โหมด AFK และรายได้ตอนไม่อยู่</summary><div><p>กดปุ่ม 💤 บนแถบด้านบนเพื่อเข้าโหมด AFK เกมจะเดินต่อเอง ตัดสินใจเหตุการณ์แบบปลอดภัย และรับรางวัลภารกิจให้ โดยไม่วาดแผนที่เพื่อประหยัดแบต</p><p>ถ้าไม่แตะจอ 10 วินาที (หรือกด 🌙 หรี่จอเลย) จอจะมืดเหมือนโหมดนอนหลับ เหลือแค่นาฬิกาจาง ๆ กับเงิน แตะจอครั้งเดียวเพื่อปลุก</p><p>ถ้าปิดเกมหรือสลับไปแอปอื่นเกิน 2 นาที กลับมาจะได้รายได้ตามกำไรเฉลี่ย 7 วันล่าสุด</p><ul><li>ปกติ: 12 วันของกำไรต่อชั่วโมง สูงสุด 8 ชม.</li><li>เปิด AFK ไว้ก่อนออก: 24 วันต่อชั่วโมง สูงสุด 12 ชม.</li><li>ถ้ากำไรเฉลี่ยติดลบจะไม่ได้รายได้ แต่ก็ไม่หักเงิน</li><li>เวลาในเกมไม่เดินระหว่างที่ไม่อยู่</li></ul></div></details>
<details class="g"><summary>การแข่งขันและคะแนน</summary><div><p>แข่งกับสายการบินคู่แข่ง 5 เจ้าด้วยคะแนนรวม ดูได้จากปุ่ม 🏆 มุมขวาบนของแผนที่ หรือในแท็บบริษัท</p><ul><li>มูลค่ากิจการ 1 คะแนนต่อ ฿2 ล้าน</li><li>ผู้โดยสารสะสม 1 คะแนนต่อ 70 คน</li><li>สินค้าทางอากาศ 1 คะแนนต่อ 1.4 ตัน</li><li>ตู้ทางเรือ 1 คะแนนต่อ 10 TEU</li><li>เรตติ้ง 1,000 คะแนนต่อดาว</li><li>ภารกิจ 120 คะแนนต่อภารกิจ</li></ul><p>ลูกศร ▲▼ บอกว่าอันดับเปลี่ยนไปเท่าไรจากเมื่อวาน</p></div></details>
<details class="g"><summary>เรตติ้ง 5 ดาว</summary><div><p>เรตติ้งโดยรวมคือค่าเฉลี่ยของ 4 ด้านที่เริ่มทำแล้ว:</p><ul><li><b>สายการบิน</b> จำนวนปลายทาง ที่นั่งเต็มใกล้ 85% สภาพเครื่อง และสัดส่วนเส้นทางที่มีกำไร</li><li><b>การเดินเรือ</b> ตู้เต็ม เส้นทางเรือที่มีกำไร ขนาดกองเรือ และระดับสาขาท่าเรือ</li><li><b>สินค้าทางอากาศ</b> ระวางเต็ม ปริมาณสินค้า และจำนวนเครื่องขนสินค้า</li><li><b>ความพอใจของผู้โดยสาร</b> ชื่อเสียง ระดับบริการ ความคุ้มค่าของราคาตั๋ว ความแออัด และเหตุเครื่องขัดข้อง</li></ul><p>เรตติ้งคำนวณใหม่ทุกวัน 0 ดาวทำให้ผู้โดยสารลด 10% ส่วน 5 ดาวเพิ่ม 10% คู่แข่งก็มีเรตติ้งในตารางอันดับ</p></div></details>
<details class="g"><summary>ภารกิจและการตัดสินใจ</summary><div><p>หน้าหลักมีภารกิจ 3 อย่างเสมอ ทำสำเร็จแล้วกดรับรางวัลเป็นเงินและชื่อเสียง บางภารกิจมีเวลาจำกัด ทุก 1–2 สัปดาห์ในเกมจะมีเรื่องให้ตัดสินใจ เช่น งานเหมาลำ สหภาพลูกเรือ ดีลลดราคาเครื่องบิน หรือโค้ดแชร์ เกมจะหยุดรอจนกว่าคุณเลือก</p></div></details>
<details class="g"><summary>สาขา</summary><div><p>สาขาท่าเรือทำงานแบบเดียวกับสาขาสนามบิน เรือต้องออกจากสาขาท่าเรือของคุณ อัปเกรดแล้วตู้สินค้าเพิ่ม 8% และค่าท่าเรือลด 15% ต่อระดับ</p><p>ทุกเส้นทางต้องออกจากสาขา เปิดสาขาได้ที่สนามบินใดก็ได้ในภูมิภาคที่ปลดล็อกแล้ว ในแท็บ "สาขา" หรือแตะสนามบินบนแผนที่ ราคาสาขาขึ้นกับขนาดเมือง และแพงขึ้น 30% ต่อสาขาที่มีอยู่</p><p>แต่ละสาขามีค่าดูแลรายวัน (สำนักงานใหญ่ฟรี) อัปเกรดได้ถึงระดับ 3 แต่ละระดับเพิ่มผู้โดยสาร 8% และลดค่าสนามบิน 15% ของทุกเส้นทางที่บินเข้าออกสนามบินนั้น แต่ค่าดูแลก็เพิ่มตามระดับ</p></div></details>
<details class="g"><summary>แผนที่และการปลดล็อก</summary><div><p>โลกแบ่งเป็น 9 ภูมิภาค มีสนามบินทั้งหมด ${CITIES.length} แห่ง เริ่มเกมคุณเห็นแค่ภูมิภาคของเมืองฐาน ที่เหลือถูกหมอกบัง เปิดเส้นทางหรือตั้งฐานได้เฉพาะเมืองในภูมิภาคที่ปลดล็อกแล้ว แตะป้าย 🔒 บนแผนที่หรือปุ่ม "ปลดล็อกแผนที่" เพื่อจ่ายเงินปลดล็อก ราคาขึ้นกับระยะทางจากฐานแรก</p><p>แท็บ "แผนที่" เปิดแผนที่ใหญ่เต็มจอ หรือกดปุ่มขยายมุมแผนที่ในหน้าหลัก ลากเพื่อเลื่อนแผนที่ บีบสองนิ้วหรือกด + − เพื่อซูม ปุ่มลูกโลกดูทั้งโลก ปุ่มเป้าซูมไปที่เส้นทางของคุณ</p><p>แผนที่ใช้แนวชายฝั่งและพรมแดนจริงจาก Natural Earth เส้นทางบินวาดตามเส้นวงกลมใหญ่ (great circle) แบบที่เครื่องบินจริงใช้ เส้นทางไกลจึงโค้งขึ้นไปทางขั้วโลก เงาสีเข้มคือด้านกลางคืนของโลก คำนวณจากเวลาในเกมและฤดูกาล</p></div></details>
<details class="g"><summary>เหตุการณ์สุ่ม</summary><div><ul><li>เทศกาล: คนและสินค้าเพิ่ม 60% 7 วัน</li><li>พายุ: งดบินเข้าออกเมืองนั้น 2 วัน แต่ค่าดูแลเครื่องยังเดิน</li><li>คู่แข่งเปิดเส้นทาง: คนลด 25% 30 วัน</li><li>น้ำมันพุ่งหรือร่วง, คลิปไวรัล, นกชนเครื่อง, คู่แข่งมีปัญหาการเงิน</li></ul><p>เมืองที่มีเหตุการณ์จะมีวงสีกระพริบบนแผนที่</p></div></details>
</div>`}

/* ---------- map (real geography: Natural Earth 1:50m via world-atlas) ---------- */
function cssv(n){return getComputedStyle(document.documentElement).getPropertyValue(n).trim()}
const RINGS=GEO.L.map(a=>{const p=new Float32Array(a.length);let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;
  for(let i=0;i<a.length;i+=2){const x=a[i]/10,y=a[i+1]/10;p[i]=x;p[i+1]=y;if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y}return {p,x0,x1,y0,y1}});
const BORDERS=GEO.B.map(a=>{const p=new Float32Array(a.length);let x0=1e9,x1=-1e9,y0=1e9,y1=-1e9;
  for(let i=0;i<a.length;i+=2){const x=a[i]/10,y=a[i+1]/10;p[i]=x;p[i+1]=y;if(x<x0)x0=x;if(x>x1)x1=x;if(y<y0)y0=y;if(y>y1)y1=y}return {p,x0,x1,y0,y1}});
const ulon=lon=>{const h=city(S.hub).lon;let l=lon;while(l-h>180)l-=360;while(l-h<-180)l+=360;return l};
const gcCache=new Map();
// Route line on the map: a straight line between the two airports (shortest way round) — the gentle bow is added when drawing.
// A true great circle loops far north on a flat map for long flights, which looked odd.
function gcPath(a,b){const key="f"+S.hub+a.c+b.c;if(gcCache.has(key))return gcCache.get(key);
  {const l0=ulon(a.lon);let l1=ulon(b.lon);while(l1-l0>180)l1-=360;while(l1-l0<-180)l1+=360;const pts=[];for(let i=0;i<=48;i++){const t=i/48;pts.push([l0+(l1-l0)*t,a.lat+(b.lat-a.lat)*t])}gcCache.set(key,pts);return pts}
  const r=Math.PI/180,toV=c=>[Math.cos(c.lat*r)*Math.cos(c.lon*r),Math.cos(c.lat*r)*Math.sin(c.lon*r),Math.sin(c.lat*r)];
  const A=toV(a),B=toV(b),om=Math.acos(clamp(A[0]*B[0]+A[1]*B[1]+A[2]*B[2],-1,1)),s=Math.sin(om)||1,n=64,pts=[];
  let prev=ulon(a.lon);
  for(let i=0;i<=n;i++){const t=i/n,f1=Math.sin((1-t)*om)/s,f2=Math.sin(t*om)/s,v=[f1*A[0]+f2*B[0],f1*A[1]+f2*B[1],f1*A[2]+f2*B[2]];
    const lat=Math.atan2(v[2],Math.hypot(v[0],v[1]))/r;let lon=Math.atan2(v[1],v[0])/r;
    while(lon-prev>180)lon-=360;while(lon-prev<-180)lon+=360;prev=lon;pts.push([lon,lat])}
  gcCache.set(key,pts);return pts}
const along=(pts,t)=>{const f=clamp(t,0,1)*(pts.length-1),i=Math.min(pts.length-2,Math.floor(f)),u=f-i;return [pts[i][0]+(pts[i+1][0]-pts[i][0])*u,pts[i][1]+(pts[i+1][1]-pts[i][1])*u]};
const SILS={},SILD={};
const ring=pts=>{let a=0;for(let i=0;i<pts.length;i++){const p=pts[i],q=pts[(i+1)%pts.length];a+=p[0]*q[1]-q[0]*p[1]}if(a>0)pts=pts.slice().reverse();return "M"+pts.map(p=>p[0].toFixed(2)+" "+p[1].toFixed(2)).join("L")+"Z"};
