  const d=S.hist.slice(-180);if(d.length<2){x.fillStyle=cssv("--muted");x.font="13px 'IBM Plex Sans Thai', sans-serif";x.fillText(_T("กราฟจะขึ้นเมื่อผ่านไปสองสามวัน"),8,H/2);return}
