  const pl=46,pr=6,pt=8,pb=18,X=i=>pl+i/(d.length-1)*(W-pl-pr),Y=v=>pt+(mx-v)/(mx-mn)*(H-pt-pb);
  x.font="11px 'IBM Plex Mono', monospace";x.fillStyle=cssv("--muted");x.strokeStyle=cssv("--grid");x.lineWidth=1;x.textBaseline="middle";
